insert into public.handbook_chapters (id, slug, part, part_title, title, summary, minutes, body_md, sources, blocks) values
(1, 'safety-first', 'A', 'Foundations', 'Safe to start', 'Who can start today, who should see a doctor first, and the signs that mean stop.', 3, 'Most adults can start exercising today. A small group should speak to a doctor first, and everyone should know the few signs that mean stop. Should you see a doctor first? Do you have chest pain, fainting, unusual breathlessness, a racing heartbeat or ankle swelling? Stop here. See a doctor before exercising. Go to the next question. Has a doctor told you that you have heart, kidney or metabolic disease such as diabetes? Get medical clearance first, then start light and build slowly. Go to the next question. Are you mostly inactive right now, exercising fewer than 3 days a week? Start at light to moderate effort and build up over weeks. Carry on, and build intensity gradually. Screening rests on three things: how active you are now, any signs or known disease, and how hard you plan to train. Normal during training Muscles burning near the end of a set Breathing hard, then recovering within a minute or two Muscle soreness a day or two later Stop and get help Chest pain, pressure or tightness Dizziness, faintness or confusion A heartbeat that feels irregular or racing Sharp or sudden joint pain Some  activity is better than none, even if you cannot reach the target yet Start low  and build slowly if you have been inactive Pregnant, recovering from surgery, or managing a long-term condition? Follow your doctor''s advice first. Levlofit will ask you and adjust.', array['Riebe D et al. Updating ACSM''s recommendations for exercise preparticipation health screening. Med Sci Sports Exerc 2015;47(11):2473-2479.', 'Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.']::text[], '{"sources": {"riebe2015": "Riebe D et al. Updating ACSM''s recommendations for exercise preparticipation health screening. Med Sci Sports Exerc 2015;47(11):2473-2479.", "who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462."}, "blocks": [{"t": "lead", "text": "Most adults can start exercising today. A small group should speak to a doctor first, and everyone should know the few signs that mean stop."}, {"t": "flow", "title": "Should you see a doctor first?", "items": [{"q": "Do you have chest pain, fainting, unusual breathlessness, a racing heartbeat or ankle swelling?", "yes": "Stop here. See a doctor before exercising.", "no": "Go to the next question."}, {"q": "Has a doctor told you that you have heart, kidney or metabolic disease such as diabetes?", "yes": "Get medical clearance first, then start light and build slowly.", "no": "Go to the next question."}, {"q": "Are you mostly inactive right now, exercising fewer than 3 days a week?", "yes": "Start at light to moderate effort and build up over weeks.", "no": "Carry on, and build intensity gradually."}], "note": "Screening rests on three things: how active you are now, any signs or known disease, and how hard you plan to train.", "source": "riebe2015"}, {"t": "compare", "do": {"title": "Normal during training", "items": ["Muscles burning near the end of a set", "Breathing hard, then recovering within a minute or two", "Muscle soreness a day or two later"]}, "dont": {"title": "Stop and get help", "items": ["Chest pain, pressure or tightness", "Dizziness, faintness or confusion", "A heartbeat that feels irregular or racing", "Sharp or sudden joint pain"]}}, {"t": "stats", "items": [{"value": "Some", "unit": "", "label": "activity is better than none, even if you cannot reach the target yet", "source": "who2020"}, {"value": "Start low", "unit": "", "label": "and build slowly if you have been inactive", "source": "who2020"}]}, {"t": "rule", "text": "Pregnant, recovering from surgery, or managing a long-term condition? Follow your doctor''s advice first. Levlofit will ask you and adjust."}]}'::jsonb),
(2, 'how-training-works', 'A', 'Foundations', 'How training works', 'Stress, recover, adapt: why you get fitter, and the weekly amounts that improve health.', 4, 'Training is a signal. You stress the body a little more than it is used to, it recovers, and it rebuilds to handle that stress next time. The adaptation loop Train Tire Recover Adapt Do a little more Four rules behind every plan Specific You get better at what you practise. Running builds running, lifting builds strength. Progressive Add a little over time: a rep, a set, a kilo or a minute. Recovered Adaptation happens between sessions, not during them. Consistent Months of regular training beat any single perfect week. Weekly aerobic activity for adults minutes a week Moderate, at least 150 min Moderate, for more benefit 300 min Or vigorous, at least 75 min Or vigorous, for more benefit 150 min 2 days a week of muscle strengthening for all major muscles Less sitting and more movement in its place benefits health at any fitness level The ACSM 2026 review of 137 systematic reviews found the biggest gains come from going from no resistance training to any resistance training. Details matter less than doing it regularly. strong', array['Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.', 'Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.']::text[], '{"sources": {"who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.", "acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026."}, "blocks": [{"t": "lead", "text": "Training is a signal. You stress the body a little more than it is used to, it recovers, and it rebuilds to handle that stress next time."}, {"t": "cycle", "title": "The adaptation loop", "items": ["Train", "Tire", "Recover", "Adapt", "Do a little more"]}, {"t": "steps", "title": "Four rules behind every plan", "items": [{"title": "Specific", "text": "You get better at what you practise. Running builds running, lifting builds strength."}, {"title": "Progressive", "text": "Add a little over time: a rep, a set, a kilo or a minute."}, {"title": "Recovered", "text": "Adaptation happens between sessions, not during them."}, {"title": "Consistent", "text": "Months of regular training beat any single perfect week."}]}, {"t": "bars", "title": "Weekly aerobic activity for adults", "unit": "minutes a week", "items": [{"label": "Moderate, at least", "value": 150, "note": "150 min"}, {"label": "Moderate, for more benefit", "value": 300, "note": "300 min"}, {"label": "Or vigorous, at least", "value": 75, "note": "75 min"}, {"label": "Or vigorous, for more benefit", "value": 150, "note": "150 min"}], "source": "who2020"}, {"t": "stats", "items": [{"value": "2", "unit": "days a week", "label": "of muscle strengthening for all major muscles", "source": "who2020"}, {"value": "Less", "unit": "sitting", "label": "and more movement in its place benefits health at any fitness level", "source": "who2020"}]}, {"t": "evidence", "text": "The ACSM 2026 review of 137 systematic reviews found the biggest gains come from going from no resistance training to any resistance training. Details matter less than doing it regularly.", "source": "acsm2026", "grade": "strong"}]}'::jsonb),
(3, 'effort-and-rir', 'A', 'Foundations', 'How hard to push', 'Reps in reserve: the simple scale Levlofit uses to set effort on every set.', 3, 'After a set, ask one question: how many more good reps could I have done? That number is your reps in reserve, or RIR. Reps in reserve scale 0 Failure No more reps possible with good form 1 Very hard One rep left 2 Hard Two reps left 3 Challenging Three reps left 4+ Moderate Four or more left 2 to 3 RIR is close enough to failure to build muscle 30 to 100 % of max all build muscle when sets end near failure Do End most working sets with 1 to 3 reps left Keep form identical on the last rep Leave an extra rep in hand while learning a lift Avoid Taking every set to total failure Grinding reps with form breaking down Trusting your RIR guess in the first week of a new lift Beginners are less accurate at judging reps in reserve than experienced lifters, and get better with practice. Start conservative. moderate', array['Zourdos MC et al. Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. J Strength Cond Res 2016;30(1):267-275.', 'Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.']::text[], '{"sources": {"zourdos2016": "Zourdos MC et al. Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. J Strength Cond Res 2016;30(1):267-275.", "acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026."}, "blocks": [{"t": "lead", "text": "After a set, ask one question: how many more good reps could I have done? That number is your reps in reserve, or RIR."}, {"t": "scale", "title": "Reps in reserve scale", "items": [{"mark": "0", "label": "Failure", "text": "No more reps possible with good form"}, {"mark": "1", "label": "Very hard", "text": "One rep left"}, {"mark": "2", "label": "Hard", "text": "Two reps left"}, {"mark": "3", "label": "Challenging", "text": "Three reps left"}, {"mark": "4+", "label": "Moderate", "text": "Four or more left"}], "source": "zourdos2016"}, {"t": "stats", "items": [{"value": "2 to 3", "unit": "RIR", "label": "is close enough to failure to build muscle", "source": "acsm2026"}, {"value": "30 to 100", "unit": "% of max", "label": "all build muscle when sets end near failure", "source": "acsm2026"}]}, {"t": "compare", "do": {"title": "Do", "items": ["End most working sets with 1 to 3 reps left", "Keep form identical on the last rep", "Leave an extra rep in hand while learning a lift"]}, "dont": {"title": "Avoid", "items": ["Taking every set to total failure", "Grinding reps with form breaking down", "Trusting your RIR guess in the first week of a new lift"]}}, {"t": "evidence", "text": "Beginners are less accurate at judging reps in reserve than experienced lifters, and get better with practice. Start conservative.", "source": "zourdos2016", "grade": "moderate"}]}'::jsonb),
(4, 'warm-up', 'A', 'Foundations', 'Warming up', 'A short warm-up that prepares you without draining strength.', 3, 'A good warm-up raises body temperature, moves the joints you are about to use, and rehearses the first exercise with light weight. A 10 minute warm-up Raise 3 to 5 minutes of easy movement: brisk walk, cycle or skipping. Mobilise Dynamic moves through full range: leg swings, arm circles, bodyweight squats. Rehearse 2 to 3 lighter sets of your first exercise, building up to your working weight. Before hard training Dynamic movements Light sets of the main lift Short static stretches if a sport needs the range Save for later Long static holds of 60 seconds or more per muscle Stretching so hard it hurts 60 seconds or more of static stretching per muscle can reduce strength and power for a short time Dynamic stretching has no negative effect and can help performance. Long static stretches cause a small, short-lived drop in force, so keep them after training. strong', array['Behm DG et al. Acute effects of muscle stretching on physical performance, range of motion, and injury incidence in healthy active individuals: a systematic review. Appl Physiol Nutr Metab 2016;41(1):1-11.', 'Warneke K et al. Revisiting the stretch-induced force deficit: a systematic review with multilevel meta-analysis of acute effects. J Sport Health Sci 2024.']::text[], '{"sources": {"behm2016": "Behm DG et al. Acute effects of muscle stretching on physical performance, range of motion, and injury incidence in healthy active individuals: a systematic review. Appl Physiol Nutr Metab 2016;41(1):1-11.", "warneke2024": "Warneke K et al. Revisiting the stretch-induced force deficit: a systematic review with multilevel meta-analysis of acute effects. J Sport Health Sci 2024."}, "blocks": [{"t": "lead", "text": "A good warm-up raises body temperature, moves the joints you are about to use, and rehearses the first exercise with light weight."}, {"t": "steps", "title": "A 10 minute warm-up", "items": [{"title": "Raise", "text": "3 to 5 minutes of easy movement: brisk walk, cycle or skipping."}, {"title": "Mobilise", "text": "Dynamic moves through full range: leg swings, arm circles, bodyweight squats."}, {"title": "Rehearse", "text": "2 to 3 lighter sets of your first exercise, building up to your working weight."}]}, {"t": "compare", "do": {"title": "Before hard training", "items": ["Dynamic movements", "Light sets of the main lift", "Short static stretches if a sport needs the range"]}, "dont": {"title": "Save for later", "items": ["Long static holds of 60 seconds or more per muscle", "Stretching so hard it hurts"]}}, {"t": "stats", "items": [{"value": "60", "unit": "seconds", "label": "or more of static stretching per muscle can reduce strength and power for a short time", "source": "behm2016"}]}, {"t": "evidence", "text": "Dynamic stretching has no negative effect and can help performance. Long static stretches cause a small, short-lived drop in force, so keep them after training.", "source": "warneke2024", "grade": "strong"}]}'::jsonb),
(5, 'sets-reps-progress', 'A', 'Foundations', 'Sets, reps and progress', 'How much to lift for strength or muscle, how to progress, and when to ease off.', 4, 'Pick the goal, then match the dose. Strength wants heavy sets, muscle wants enough hard sets, and both want slow, steady progress. Goal Load Volume Frequency Strength 80% of max or more 2 to 3 sets per lift 2 or more sessions a week Muscle size 30 to 100% of max, near failure 10 or more sets per muscle a week Each muscle 2 times a week General health Any challenging load All major muscles 2 or more days a week Double progression, the simplest way to progress Pick a rep range For example 8 to 12 reps. Add reps Stay at the same weight until every set reaches the top of the range. Add weight Increase the load a little and drop back to the bottom of the range. Repeat Small steps, every week or two. Example: 3 full-body days Mon Full body Tue Walk Wed Full body Thu Rest Fri Full body Sat Walk or sport Sun Rest 4 to 8 weeks between planned deloads is common practice 40 to 50 % less volume during a deload week Expert coaches agree a deload is a planned lighter period to shed fatigue and come back ready. It is not a week off. consensus', array['Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.', 'Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87.']::text[], '{"sources": {"acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.", "bell2023": "Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87."}, "blocks": [{"t": "lead", "text": "Pick the goal, then match the dose. Strength wants heavy sets, muscle wants enough hard sets, and both want slow, steady progress."}, {"t": "table", "head": ["Goal", "Load", "Volume", "Frequency"], "rows": [["Strength", "80% of max or more", "2 to 3 sets per lift", "2 or more sessions a week"], ["Muscle size", "30 to 100% of max, near failure", "10 or more sets per muscle a week", "Each muscle 2 times a week"], ["General health", "Any challenging load", "All major muscles", "2 or more days a week"]], "source": "acsm2026"}, {"t": "steps", "title": "Double progression, the simplest way to progress", "items": [{"title": "Pick a rep range", "text": "For example 8 to 12 reps."}, {"title": "Add reps", "text": "Stay at the same weight until every set reaches the top of the range."}, {"title": "Add weight", "text": "Increase the load a little and drop back to the bottom of the range."}, {"title": "Repeat", "text": "Small steps, every week or two."}]}, {"t": "week", "title": "Example: 3 full-body days", "days": [{"day": "Mon", "label": "Full body", "kind": "strength"}, {"day": "Tue", "label": "Walk", "kind": "cardio"}, {"day": "Wed", "label": "Full body", "kind": "strength"}, {"day": "Thu", "label": "Rest", "kind": "rest"}, {"day": "Fri", "label": "Full body", "kind": "strength"}, {"day": "Sat", "label": "Walk or sport", "kind": "cardio"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "stats", "items": [{"value": "4 to 8", "unit": "weeks", "label": "between planned deloads is common practice", "source": "bell2023"}, {"value": "40 to 50", "unit": "% less volume", "label": "during a deload week", "source": "bell2023"}]}, {"t": "evidence", "text": "Expert coaches agree a deload is a planned lighter period to shed fatigue and come back ready. It is not a week off.", "source": "bell2023", "grade": "consensus"}]}'::jsonb),
(6, 'food-basics', 'A', 'Foundations', 'Food for training', 'The Indian plate, how much protein you need, and the best vegetarian and non-vegetarian sources.', 5, 'Build the plate first, then fix protein. Most Indian meals are rich in cereal and short on protein, so that is where training changes things. My Plate for the Day, per 2000 kcal Vegetables and greens 400 g Cereals and millets 250 g Fruits 100 g Pulses, eggs or meat 85 g Nuts and seeds 35 g Oils and fats 27 g Protein per kg of body weight, per day g per kg Inactive adult, Indian RDA 0.83 g Training adult, lower end 1.4 g Training adult, upper end 2.0 g 20 to 40 g protein per meal, spread every 3 to 4 hours 30 % or less of daily energy from fat 0.83 g per kg is the Indian RDA for a healthy, inactive adult Food, per 100 g raw Protein Energy Masoor dal 24.4 g 322 kcal Moong, whole 22.5 g 294 kcal Chicken breast, skinless 21.8 g 168 kcal Rajma, red 19.9 g 299 kcal Paneer 18.9 g 258 kcal Kala chana 18.8 g 287 kcal Egg, whole 13.3 g 135 kcal Atta 10.6 g 320 kcal Cow milk 3.3 g 73 kcal Across 41 clinical studies, soy protein and isoflavones did not change testosterone or oestrogen in men, at any dose tested. Levlofit still caps soya chunks at 50 g dry a day, for variety rather than safety. strong', array['ICMR-National Institute of Nutrition. Dietary Guidelines for Indians, 2024.', 'ICMR-National Institute of Nutrition. Nutrient Requirements for Indians (RDA and EAR), 2020.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.', 'Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.', 'Reed KE et al. Neither soy nor isoflavone intake affects male reproductive hormones: an expanded and updated meta-analysis of clinical studies. Reprod Toxicol 2021;100:60-67.']::text[], '{"sources": {"icmr2024": "ICMR-National Institute of Nutrition. Dietary Guidelines for Indians, 2024.", "icmr2020": "ICMR-National Institute of Nutrition. Nutrient Requirements for Indians (RDA and EAR), 2020.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.", "ifct2017": "Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.", "soy2021": "Reed KE et al. Neither soy nor isoflavone intake affects male reproductive hormones: an expanded and updated meta-analysis of clinical studies. Reprod Toxicol 2021;100:60-67."}, "blocks": [{"t": "lead", "text": "Build the plate first, then fix protein. Most Indian meals are rich in cereal and short on protein, so that is where training changes things."}, {"t": "plate", "title": "My Plate for the Day, per 2000 kcal", "items": [{"label": "Vegetables and greens", "share": 400, "note": "400 g"}, {"label": "Cereals and millets", "share": 250, "note": "250 g"}, {"label": "Fruits", "share": 100, "note": "100 g"}, {"label": "Pulses, eggs or meat", "share": 85, "note": "85 g"}, {"label": "Nuts and seeds", "share": 35, "note": "35 g"}, {"label": "Oils and fats", "share": 27, "note": "27 g"}], "source": "icmr2024"}, {"t": "bars", "title": "Protein per kg of body weight, per day", "unit": "g per kg", "items": [{"label": "Inactive adult, Indian RDA", "value": 0.83, "note": "0.83 g"}, {"label": "Training adult, lower end", "value": 1.4, "note": "1.4 g"}, {"label": "Training adult, upper end", "value": 2.0, "note": "2.0 g"}], "source": "issnprotein"}, {"t": "stats", "items": [{"value": "20 to 40", "unit": "g", "label": "protein per meal, spread every 3 to 4 hours", "source": "issnprotein"}, {"value": "30", "unit": "% or less", "label": "of daily energy from fat", "source": "icmr2024"}, {"value": "0.83", "unit": "g per kg", "label": "is the Indian RDA for a healthy, inactive adult", "source": "icmr2020"}]}, {"t": "table", "head": ["Food, per 100 g raw", "Protein", "Energy"], "rows": [["Masoor dal", "24.4 g", "322 kcal"], ["Moong, whole", "22.5 g", "294 kcal"], ["Chicken breast, skinless", "21.8 g", "168 kcal"], ["Rajma, red", "19.9 g", "299 kcal"], ["Paneer", "18.9 g", "258 kcal"], ["Kala chana", "18.8 g", "287 kcal"], ["Egg, whole", "13.3 g", "135 kcal"], ["Atta", "10.6 g", "320 kcal"], ["Cow milk", "3.3 g", "73 kcal"]], "source": "ifct2017"}, {"t": "evidence", "text": "Across 41 clinical studies, soy protein and isoflavones did not change testosterone or oestrogen in men, at any dose tested. Levlofit still caps soya chunks at 50 g dry a day, for variety rather than safety.", "source": "soy2021", "grade": "strong"}]}'::jsonb),
(7, 'water', 'A', 'Foundations', 'Water and sweat', 'How to tell if you are drinking enough in Indian heat, without guesswork.', 2, 'Start training well hydrated, and drink enough during long or hot sessions to avoid losing more than 2% of your body weight. 2 % of body weight lost as sweat is where performance starts to suffer Check your sweat loss Weigh before Light clothes, after using the toilet. Train Note how much you drink. Weigh after Towel off first. Compare A 70 kg person should lose under 1.4 kg. More than that? Drink more next time. Signs you are fine Pale yellow urine Body weight back to normal by the next morning Signs to drink more Dark urine, or very little of it Headache or dizziness after training Long sessions in heat lose salt as well as water. Salted food, lassi or chaas after training helps replace it.', array['Sawka MN et al. American College of Sports Medicine position stand: exercise and fluid replacement. Med Sci Sports Exerc 2007;39(2):377-390.']::text[], '{"sources": {"acsmfluid": "Sawka MN et al. American College of Sports Medicine position stand: exercise and fluid replacement. Med Sci Sports Exerc 2007;39(2):377-390."}, "blocks": [{"t": "lead", "text": "Start training well hydrated, and drink enough during long or hot sessions to avoid losing more than 2% of your body weight."}, {"t": "stats", "items": [{"value": "2", "unit": "% of body weight", "label": "lost as sweat is where performance starts to suffer", "source": "acsmfluid"}]}, {"t": "steps", "title": "Check your sweat loss", "items": [{"title": "Weigh before", "text": "Light clothes, after using the toilet."}, {"title": "Train", "text": "Note how much you drink."}, {"title": "Weigh after", "text": "Towel off first."}, {"title": "Compare", "text": "A 70 kg person should lose under 1.4 kg. More than that? Drink more next time."}]}, {"t": "compare", "do": {"title": "Signs you are fine", "items": ["Pale yellow urine", "Body weight back to normal by the next morning"]}, "dont": {"title": "Signs to drink more", "items": ["Dark urine, or very little of it", "Headache or dizziness after training"]}}, {"t": "rule", "text": "Long sessions in heat lose salt as well as water. Salted food, lassi or chaas after training helps replace it."}]}'::jsonb),
(8, 'body-measures', 'A', 'Foundations', 'Reading your body numbers', 'BMI cut-offs for Indians, why waist matters, and what the numbers cannot tell you.', 3, 'Asian Indians carry more health risk at a lower weight than Western cut-offs assume, so Levlofit uses Indian cut-offs and your waist. BMI for Asian Indians kg/m² Underweight Normal Overweight Obese Waist to height ratio ratio Healthy Increased risk High risk Measure your waist Find the spot Midway between your lowest rib and the top of your hip bone. Breathe out Relax, do not pull the belly in. Read Tape level and snug, not tight. Divide Waist in cm divided by height in cm. BMI is good for Quick screening Tracking change in the same person BMI misses Muscle versus fat Where fat is stored', array['Misra A et al. Consensus statement for diagnosis of obesity, abdominal obesity and the metabolic syndrome for Asian Indians. J Assoc Physicians India 2009;57:163-170.', 'National Institute for Health and Care Excellence. Obesity: identification, assessment and management (waist-to-height ratio update), 2022.']::text[], '{"sources": {"misra2009": "Misra A et al. Consensus statement for diagnosis of obesity, abdominal obesity and the metabolic syndrome for Asian Indians. J Assoc Physicians India 2009;57:163-170.", "nice2022": "National Institute for Health and Care Excellence. Obesity: identification, assessment and management (waist-to-height ratio update), 2022."}, "blocks": [{"t": "lead", "text": "Asian Indians carry more health risk at a lower weight than Western cut-offs assume, so Levlofit uses Indian cut-offs and your waist."}, {"t": "band", "title": "BMI for Asian Indians", "unit": "kg/m²", "ranges": [{"from": 14, "to": 18, "label": "Underweight", "tone": "warn"}, {"from": 18, "to": 23, "label": "Normal", "tone": "good"}, {"from": 23, "to": 25, "label": "Overweight", "tone": "warn"}, {"from": 25, "to": 35, "label": "Obese", "tone": "bad"}], "source": "misra2009"}, {"t": "band", "title": "Waist to height ratio", "unit": "ratio", "ranges": [{"from": 0.3, "to": 0.5, "label": "Healthy", "tone": "good"}, {"from": 0.5, "to": 0.6, "label": "Increased risk", "tone": "warn"}, {"from": 0.6, "to": 0.8, "label": "High risk", "tone": "bad"}], "source": "nice2022"}, {"t": "steps", "title": "Measure your waist", "items": [{"title": "Find the spot", "text": "Midway between your lowest rib and the top of your hip bone."}, {"title": "Breathe out", "text": "Relax, do not pull the belly in."}, {"title": "Read", "text": "Tape level and snug, not tight."}, {"title": "Divide", "text": "Waist in cm divided by height in cm."}]}, {"t": "compare", "do": {"title": "BMI is good for", "items": ["Quick screening", "Tracking change in the same person"]}, "dont": {"title": "BMI misses", "items": ["Muscle versus fat", "Where fat is stored"]}}]}'::jsonb),
(9, 'sleep-recovery', 'A', 'Foundations', 'Sleep and recovery', 'Why sleep is part of training, and how to spot too much fatigue.', 3, 'You train in the gym and improve while you rest. Sleep is part of the plan, not time off from it. 7+ hours of sleep a night, regularly, for adults 18 to 60 Recovery in a week Hard session Easy day or rest Sleep 7+ hours Next hard session Recovering well Weights feel normal or lighter You look forward to training Sleep is steady Too much fatigue Performance drops for more than a week Motivation keeps falling Aches that do not settle Hard and easy days Mon Hard Tue Easy walk Wed Hard Thu Rest Fri Hard Sat Easy Sun Rest Coaches use planned lighter weeks, called deloads, to clear fatigue before it becomes a problem. consensus', array['Watson NF et al. Recommended amount of sleep for a healthy adult: a joint consensus statement of the AASM and SRS. J Clin Sleep Med 2015;11(6):591-592.', 'Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87.']::text[], '{"sources": {"aasm2015": "Watson NF et al. Recommended amount of sleep for a healthy adult: a joint consensus statement of the AASM and SRS. J Clin Sleep Med 2015;11(6):591-592.", "bell2023": "Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87."}, "blocks": [{"t": "lead", "text": "You train in the gym and improve while you rest. Sleep is part of the plan, not time off from it."}, {"t": "stats", "items": [{"value": "7+", "unit": "hours", "label": "of sleep a night, regularly, for adults 18 to 60", "source": "aasm2015"}]}, {"t": "cycle", "title": "Recovery in a week", "items": ["Hard session", "Easy day or rest", "Sleep 7+ hours", "Next hard session"]}, {"t": "compare", "do": {"title": "Recovering well", "items": ["Weights feel normal or lighter", "You look forward to training", "Sleep is steady"]}, "dont": {"title": "Too much fatigue", "items": ["Performance drops for more than a week", "Motivation keeps falling", "Aches that do not settle"]}}, {"t": "week", "title": "Hard and easy days", "days": [{"day": "Mon", "label": "Hard", "kind": "strength"}, {"day": "Tue", "label": "Easy walk", "kind": "cardio"}, {"day": "Wed", "label": "Hard", "kind": "strength"}, {"day": "Thu", "label": "Rest", "kind": "rest"}, {"day": "Fri", "label": "Hard", "kind": "strength"}, {"day": "Sat", "label": "Easy", "kind": "mobility"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "evidence", "text": "Coaches use planned lighter weeks, called deloads, to clear fatigue before it becomes a problem.", "source": "bell2023", "grade": "consensus"}]}'::jsonb),
(10, 'supplements', 'A', 'Foundations', 'Supplements that work', 'Creatine, caffeine and protein powder: doses, timing and what they really do.', 4, 'Food first. A few supplements have strong evidence and can help. None replaces training, sleep or enough protein from meals. Supplement Dose Timing Creatine monohydrate 3 to 5 g a day Any time, every day Caffeine 3 to 6 mg per kg About 60 min before Protein powder 20 to 40 g a serving When meals fall short 3 to 5 g a day of creatine keeps muscle stores full, no loading needed 0.3 g per kg a day for 5 to 7 days fills stores faster, if you choose to load 3 to 6 mg per kg of caffeine improves performance, about 60 minutes before 9 mg per kg of caffeine and above brings more side effects, with no extra benefit Caffeine for a 70 kg person mg Effective, low end (3 mg/kg) 210 mg Effective, high end (6 mg/kg) 420 mg More side effects (9 mg/kg) 630 mg Creatine has been studied for up to 5 years at doses up to 30 g a day in healthy people and was safe and well tolerated. Protein powder is simply protein: a serving counts the same as protein from food. strong Worth it Creatine monohydrate for strength and muscle Caffeine for performance, if it suits you Protein powder if food cannot reach your target Be careful Caffeine late in the day, it can cut sleep Any supplement with a health condition: ask a doctor first', array['Kreider RB et al. International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. J Int Soc Sports Nutr 2017;14:18.', 'Guest NS et al. International Society of Sports Nutrition position stand: caffeine and exercise performance. J Int Soc Sports Nutr 2021;18:1.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.']::text[], '{"sources": {"issncreatine": "Kreider RB et al. International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. J Int Soc Sports Nutr 2017;14:18.", "issncaffeine": "Guest NS et al. International Society of Sports Nutrition position stand: caffeine and exercise performance. J Int Soc Sports Nutr 2021;18:1.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20."}, "blocks": [{"t": "lead", "text": "Food first. A few supplements have strong evidence and can help. None replaces training, sleep or enough protein from meals."}, {"t": "table", "head": ["Supplement", "Dose", "Timing"], "rows": [["Creatine monohydrate", "3 to 5 g a day", "Any time, every day"], ["Caffeine", "3 to 6 mg per kg", "About 60 min before"], ["Protein powder", "20 to 40 g a serving", "When meals fall short"]], "source": null}, {"t": "stats", "items": [{"value": "3 to 5", "unit": "g a day", "label": "of creatine keeps muscle stores full, no loading needed", "source": "issncreatine"}, {"value": "0.3", "unit": "g per kg", "label": "a day for 5 to 7 days fills stores faster, if you choose to load", "source": "issncreatine"}, {"value": "3 to 6", "unit": "mg per kg", "label": "of caffeine improves performance, about 60 minutes before", "source": "issncaffeine"}, {"value": "9", "unit": "mg per kg", "label": "of caffeine and above brings more side effects, with no extra benefit", "source": "issncaffeine"}]}, {"t": "bars", "title": "Caffeine for a 70 kg person", "unit": "mg", "items": [{"label": "Effective, low end (3 mg/kg)", "value": 210, "note": "210 mg"}, {"label": "Effective, high end (6 mg/kg)", "value": 420, "note": "420 mg"}, {"label": "More side effects (9 mg/kg)", "value": 630, "note": "630 mg"}], "source": "issncaffeine"}, {"t": "evidence", "text": "Creatine has been studied for up to 5 years at doses up to 30 g a day in healthy people and was safe and well tolerated. Protein powder is simply protein: a serving counts the same as protein from food.", "source": "issncreatine", "grade": "strong"}, {"t": "compare", "do": {"title": "Worth it", "items": ["Creatine monohydrate for strength and muscle", "Caffeine for performance, if it suits you", "Protein powder if food cannot reach your target"]}, "dont": {"title": "Be careful", "items": ["Caffeine late in the day, it can cut sleep", "Any supplement with a health condition: ask a doctor first"]}}]}'::jsonb),
(11, 'one-step-at-a-time', 'B', 'Getting better', 'One goal at a time', 'Why Levlofit builds your foundation first and adds goals as you level up.', 3, 'Wanting to get strong, run and look good all at once is normal. Training all of it from day one is how beginners stall. Where do you start? Can you squat, hinge, push and pull with good form? Build your main goal first Foundation phase first Has your main goal reached Level 2? Add a second goal Keep building the main goal Your level, not your wish list, decides how many goals you train. How Levlofit levels you up Check your level Answer a short test for each goal based on what you can do today. Foundation Full-body basics and your main goal, 2 to 3 days a week. Pass the check Each level lists what to show before moving up. Unlock the next goal Extra goals switch on one at a time as your main goal climbs. Stack goals when Your main goal is past the basics You recover well between sessions Wait when Form on basic lifts is not solid yet Lots of running would compete with your strength work More interference on strength and size from frequent, long running sessions Combining endurance and strength training costs some strength, size and especially power gains, and the cost grows with how often and how long the endurance sessions are. strong', array['Wilson JM et al. Concurrent training: a meta-analysis examining interference of aerobic and resistance exercises. J Strength Cond Res 2012;26(8):2293-2307.', 'Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.']::text[], '{"sources": {"wilson2012": "Wilson JM et al. Concurrent training: a meta-analysis examining interference of aerobic and resistance exercises. J Strength Cond Res 2012;26(8):2293-2307.", "acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026."}, "blocks": [{"t": "lead", "text": "Wanting to get strong, run and look good all at once is normal. Training all of it from day one is how beginners stall."}, {"t": "flow", "title": "Where do you start?", "items": [{"q": "Can you squat, hinge, push and pull with good form?", "yes": "Build your main goal first", "no": "Foundation phase first"}, {"q": "Has your main goal reached Level 2?", "yes": "Add a second goal", "no": "Keep building the main goal"}], "note": "Your level, not your wish list, decides how many goals you train.", "source": "acsm2026"}, {"t": "steps", "title": "How Levlofit levels you up", "items": [{"title": "Check your level", "text": "Answer a short test for each goal based on what you can do today."}, {"title": "Foundation", "text": "Full-body basics and your main goal, 2 to 3 days a week."}, {"title": "Pass the check", "text": "Each level lists what to show before moving up."}, {"title": "Unlock the next goal", "text": "Extra goals switch on one at a time as your main goal climbs."}]}, {"t": "compare", "do": {"title": "Stack goals when", "items": ["Your main goal is past the basics", "You recover well between sessions"]}, "dont": {"title": "Wait when", "items": ["Form on basic lifts is not solid yet", "Lots of running would compete with your strength work"]}}, {"t": "stats", "items": [{"value": "More", "unit": "interference", "label": "on strength and size from frequent, long running sessions", "source": "wilson2012"}]}, {"t": "evidence", "text": "Combining endurance and strength training costs some strength, size and especially power gains, and the cost grows with how often and how long the endurance sessions are.", "source": "wilson2012", "grade": "strong"}]}'::jsonb),
(12, 'rest-between-sets', 'B', 'Getting better', 'Rest between sets', 'How long to rest, and how the rest timer in your session helps.', 2, 'Rest long enough to repeat good reps. Cutting rest short saves minutes but costs quality. Rest to aim for minutes Big lifts for strength 2 min or more Muscle building over 1 min Light accessory work about 1 min 2 minutes or more of rest maximises strength gains 60 seconds plus gives a small edge for muscle growth Using the rest timer Tick the set The timer starts on its own. Breathe and reset Sip water and think about the next set. Go when ready Skip early if you feel fresh, add time if not. Strength improves with short rests too, but rests of 2 minutes or more give the most strength in both trained and untrained people. moderate', array['Grgic J, Schoenfeld BJ, Skrepnik M, Davies TB, Mikulic P. Effects of rest interval duration in resistance training on measures of muscular strength: a systematic review. Sports Med 2018;48(1):137-151.', 'Singer A et al. Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy. Front Sports Act Living 2024;6:1429789.']::text[], '{"sources": {"grgic2018": "Grgic J, Schoenfeld BJ, Skrepnik M, Davies TB, Mikulic P. Effects of rest interval duration in resistance training on measures of muscular strength: a systematic review. Sports Med 2018;48(1):137-151.", "singer2024": "Singer A et al. Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy. Front Sports Act Living 2024;6:1429789."}, "blocks": [{"t": "lead", "text": "Rest long enough to repeat good reps. Cutting rest short saves minutes but costs quality."}, {"t": "bars", "title": "Rest to aim for", "unit": "minutes", "items": [{"label": "Big lifts for strength", "value": 2, "note": "2 min or more"}, {"label": "Muscle building", "value": 1.5, "note": "over 1 min"}, {"label": "Light accessory work", "value": 1, "note": "about 1 min"}], "source": "grgic2018"}, {"t": "stats", "items": [{"value": "2", "unit": "minutes or more", "label": "of rest maximises strength gains", "source": "grgic2018"}, {"value": "60", "unit": "seconds plus", "label": "gives a small edge for muscle growth", "source": "singer2024"}]}, {"t": "steps", "title": "Using the rest timer", "items": [{"title": "Tick the set", "text": "The timer starts on its own."}, {"title": "Breathe and reset", "text": "Sip water and think about the next set."}, {"title": "Go when ready", "text": "Skip early if you feel fresh, add time if not."}]}, {"t": "evidence", "text": "Strength improves with short rests too, but rests of 2 minutes or more give the most strength in both trained and untrained people.", "source": "grgic2018", "grade": "moderate"}]}'::jsonb),
(13, 'daily-steps', 'B', 'Getting better', 'Daily steps', 'How many steps actually matter, and why 10,000 is not a magic number.', 2, 'Walking more is one of the simplest health wins, and you do not need 10,000 steps to get most of it. Where the benefit levels off steps a day Adults 60 and over 6,000 to 8,000 Adults under 60 8,000 to 10,000 40 to 53 % lower risk of death in the most active step groups compared with the least Add steps without trying Walk after meals Ten minutes after lunch and dinner adds up fast. Take calls standing Pace while you talk. Stairs Skip the lift for a few floors. More daily steps went with lower risk, and the benefit levelled off at a lower count for older adults. strong', array['Paluch AE et al. Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Lancet Public Health 2022;7(3):e219-e228.', 'Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.']::text[], '{"sources": {"paluch2022": "Paluch AE et al. Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Lancet Public Health 2022;7(3):e219-e228.", "who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462."}, "blocks": [{"t": "lead", "text": "Walking more is one of the simplest health wins, and you do not need 10,000 steps to get most of it."}, {"t": "bars", "title": "Where the benefit levels off", "unit": "steps a day", "items": [{"label": "Adults 60 and over", "value": 7000, "note": "6,000 to 8,000"}, {"label": "Adults under 60", "value": 9000, "note": "8,000 to 10,000"}], "source": "paluch2022"}, {"t": "stats", "items": [{"value": "40 to 53", "unit": "% lower", "label": "risk of death in the most active step groups compared with the least", "source": "paluch2022"}]}, {"t": "steps", "title": "Add steps without trying", "items": [{"title": "Walk after meals", "text": "Ten minutes after lunch and dinner adds up fast."}, {"title": "Take calls standing", "text": "Pace while you talk."}, {"title": "Stairs", "text": "Skip the lift for a few floors."}]}, {"t": "evidence", "text": "More daily steps went with lower risk, and the benefit levelled off at a lower count for older adults.", "source": "paluch2022", "grade": "strong"}]}'::jsonb),
(14, 'tracking-progress', 'B', 'Getting better', 'Tracking that tells the truth', 'Weigh-ins, tape and photos: what each shows and how often to use it.', 3, 'The scale moves with water, food and salt. Trends over weeks, the tape and photos together show what is really changing. Tool How often Shows Scale Daily or weekly, same time Weight trend Tape Every 2 to 4 weeks Where size changes Photos Every 4 weeks Shape over months Training log Every session Strength going up Make it consistent Same time Morning, after the toilet, before food. Same conditions Same light, pose and distance for photos. Read the trend Look at the line over weeks, not one reading. Good signs Waist down while strength goes up Weight trend moving at the planned rate Not a problem A heavier day after a salty meal Weight steady while the tape shrinks Across 17 studies, regular self-weighing went with more weight loss and was not linked to anxiety or low mood. moderate', array['Zheng Y et al. Self-weighing in weight management: a systematic literature review. Obesity 2015;23(2):256-265.']::text[], '{"sources": {"zheng2015": "Zheng Y et al. Self-weighing in weight management: a systematic literature review. Obesity 2015;23(2):256-265."}, "blocks": [{"t": "lead", "text": "The scale moves with water, food and salt. Trends over weeks, the tape and photos together show what is really changing."}, {"t": "table", "head": ["Tool", "How often", "Shows"], "rows": [["Scale", "Daily or weekly, same time", "Weight trend"], ["Tape", "Every 2 to 4 weeks", "Where size changes"], ["Photos", "Every 4 weeks", "Shape over months"], ["Training log", "Every session", "Strength going up"]], "source": null}, {"t": "steps", "title": "Make it consistent", "items": [{"title": "Same time", "text": "Morning, after the toilet, before food."}, {"title": "Same conditions", "text": "Same light, pose and distance for photos."}, {"title": "Read the trend", "text": "Look at the line over weeks, not one reading."}]}, {"t": "compare", "do": {"title": "Good signs", "items": ["Waist down while strength goes up", "Weight trend moving at the planned rate"]}, "dont": {"title": "Not a problem", "items": ["A heavier day after a salty meal", "Weight steady while the tape shrinks"]}}, {"t": "evidence", "text": "Across 17 studies, regular self-weighing went with more weight loss and was not linked to anxiety or low mood.", "source": "zheng2015", "grade": "moderate"}]}'::jsonb),
(15, 'habits', 'B', 'Getting better', 'Building habits that last', 'How long habits take to form, and why one missed day does not matter.', 2, 'Motivation comes and goes. Habits carry you on the days it does not show up. 66 days median time for a daily habit to feel automatic 18 to 254 days the real range: some habits take far longer Make a habit stick Anchor it Tie it to something you already do, like after brushing your teeth. Start tiny Two minutes of the habit beats a perfect plan you skip. Track it Tick it off in the Habits tab. Miss once, not twice One missed day barely affects the habit. Daily water, from all drinks and food litres Men 2.5 L Women 2.0 L Missing a single day did not meaningfully slow habit formation in the study. moderate', array['Lally P, van Jaarsveld CHM, Potts HWW, Wardle J. How are habits formed: modelling habit formation in the real world. Eur J Soc Psychol 2010;40(6):998-1009.', 'EFSA Panel on Dietetic Products, Nutrition and Allergies. Scientific opinion on dietary reference values for water. EFSA Journal 2010;8(3):1459.']::text[], '{"sources": {"lally2010": "Lally P, van Jaarsveld CHM, Potts HWW, Wardle J. How are habits formed: modelling habit formation in the real world. Eur J Soc Psychol 2010;40(6):998-1009.", "efsa2010": "EFSA Panel on Dietetic Products, Nutrition and Allergies. Scientific opinion on dietary reference values for water. EFSA Journal 2010;8(3):1459."}, "blocks": [{"t": "lead", "text": "Motivation comes and goes. Habits carry you on the days it does not show up."}, {"t": "stats", "items": [{"value": "66", "unit": "days", "label": "median time for a daily habit to feel automatic", "source": "lally2010"}, {"value": "18 to 254", "unit": "days", "label": "the real range: some habits take far longer", "source": "lally2010"}]}, {"t": "steps", "title": "Make a habit stick", "items": [{"title": "Anchor it", "text": "Tie it to something you already do, like after brushing your teeth."}, {"title": "Start tiny", "text": "Two minutes of the habit beats a perfect plan you skip."}, {"title": "Track it", "text": "Tick it off in the Habits tab."}, {"title": "Miss once, not twice", "text": "One missed day barely affects the habit."}]}, {"t": "bars", "title": "Daily water, from all drinks and food", "unit": "litres", "items": [{"label": "Men", "value": 2.5, "note": "2.5 L"}, {"label": "Women", "value": 2.0, "note": "2.0 L"}], "source": "efsa2010"}, {"t": "evidence", "text": "Missing a single day did not meaningfully slow habit formation in the study.", "source": "lally2010", "grade": "moderate"}]}'::jsonb),
(16, 'calories', 'C', 'Food and body', 'Calories and energy balance', 'How Levlofit estimates what you burn, and how eating above or below it changes your weight.', 4, 'Your weight trend follows energy balance: eat less than you burn and you lose, eat more and you gain. Levlofit estimates your burn, then sets food to match your goal. How your calorie target is built Resting burn (BMR) The Mifflin-St Jeor equation: weight, height, age and sex give the energy you use at complete rest. Activity BMR is multiplied by 1.2 for a desk day up to 1.725 for a very active life, using your job or your training, whichever is higher. Goal Fat loss eats about 15% below that, muscle gain about 10% above, everything else at maintenance. Floor Your target never goes below your BMR. Mifflin-St Jeor Formula, kcal a day Men 10 x kg + 6.25 x cm - 5 x age + 5 Women 10 x kg + 6.25 x cm - 5 x age - 161 Activity multipliers x BMR Desk day, little walking 1.2 Light activity or 1 to 3 sessions 1.375 Active, 4 to 5 sessions 1.55 Very active, 6+ sessions or physical job 1.725 Why scale weight jumps day to day Salt and carbs hold water Weight up 0.5 to 1 kg Water settles The trend shows the truth A moderate deficit preserves muscle and training quality better than a crash diet; maintenance with high protein suits beginners trying to lose fat and gain muscle together. strong 2 to 3 weeks of weight trend in Progress beat any formula; adjust from real data', array['Mifflin MD, St Jeor ST et al. A new predictive equation for resting energy expenditure in healthy individuals. Am J Clin Nutr 1990;51(2):241-247.', 'Aragon AA et al. International Society of Sports Nutrition position stand: diets and body composition. J Int Soc Sports Nutr 2017;14:16.']::text[], '{"sources": {"mifflin1990": "Mifflin MD, St Jeor ST et al. A new predictive equation for resting energy expenditure in healthy individuals. Am J Clin Nutr 1990;51(2):241-247.", "aragon2017": "Aragon AA et al. International Society of Sports Nutrition position stand: diets and body composition. J Int Soc Sports Nutr 2017;14:16."}, "blocks": [{"t": "lead", "text": "Your weight trend follows energy balance: eat less than you burn and you lose, eat more and you gain. Levlofit estimates your burn, then sets food to match your goal."}, {"t": "steps", "title": "How your calorie target is built", "items": [{"title": "Resting burn (BMR)", "text": "The Mifflin-St Jeor equation: weight, height, age and sex give the energy you use at complete rest."}, {"title": "Activity", "text": "BMR is multiplied by 1.2 for a desk day up to 1.725 for a very active life, using your job or your training, whichever is higher."}, {"title": "Goal", "text": "Fat loss eats about 15% below that, muscle gain about 10% above, everything else at maintenance."}, {"title": "Floor", "text": "Your target never goes below your BMR."}]}, {"t": "table", "head": ["Mifflin-St Jeor", "Formula, kcal a day"], "rows": [["Men", "10 x kg + 6.25 x cm - 5 x age + 5"], ["Women", "10 x kg + 6.25 x cm - 5 x age - 161"]], "source": "mifflin1990"}, {"t": "bars", "title": "Activity multipliers", "unit": "x BMR", "items": [{"label": "Desk day, little walking", "value": 1.2, "note": "1.2"}, {"label": "Light activity or 1 to 3 sessions", "value": 1.375, "note": "1.375"}, {"label": "Active, 4 to 5 sessions", "value": 1.55, "note": "1.55"}, {"label": "Very active, 6+ sessions or physical job", "value": 1.725, "note": "1.725"}], "source": null}, {"t": "cycle", "title": "Why scale weight jumps day to day", "items": ["Salt and carbs hold water", "Weight up 0.5 to 1 kg", "Water settles", "The trend shows the truth"]}, {"t": "evidence", "text": "A moderate deficit preserves muscle and training quality better than a crash diet; maintenance with high protein suits beginners trying to lose fat and gain muscle together.", "source": "aragon2017", "grade": "strong"}, {"t": "stats", "items": [{"value": "2 to 3", "unit": "weeks", "label": "of weight trend in Progress beat any formula; adjust from real data"}]}]}'::jsonb),
(17, 'fat-loss', 'C', 'Food and body', 'Losing fat, keeping muscle', 'The pace that protects muscle, the protein that helps, and what to do when progress stalls.', 4, 'Fat loss is a slow, steady deficit with heavy training and high protein. Lose too fast and you lose muscle and strength with the fat. Weekly weight loss % of body weight Slow and very safe Target pace Fast, muscle at risk Too fast 0.5 to 1 % a week weight loss keeps the most muscle 2.0 g per kg protein a day while dieting, the top of the ISSN range Keeps muscle Lifting heavy 2 to 4 times a week Protein at every meal Losing about 0.35 to 0.7 kg a week if you weigh 70 kg 7 or more hours of sleep Costs muscle Crash diets and skipped meals Swapping lifting for only cardio Dropping protein to save calories Weight not moving? Has the weekly average been flat for 3 weeks or more? Go to the next question. Wait. Water can hide fat loss for a week or two. Are you logging food honestly, including oil and snacks? Cut about 100 to 200 kcal a day, or add 2000 daily steps. Track for one week first; most stalls are hidden intake. Reviews of contest preparation find slower loss rates protect lean mass, and protein above normal needs helps most when lean and in a deficit. moderate', array['Helms ER, Aragon AA, Fitschen PJ. Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. J Int Soc Sports Nutr 2014;11:20.', 'Aragon AA et al. International Society of Sports Nutrition position stand: diets and body composition. J Int Soc Sports Nutr 2017;14:16.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.']::text[], '{"sources": {"helms2014": "Helms ER, Aragon AA, Fitschen PJ. Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. J Int Soc Sports Nutr 2014;11:20.", "aragon2017": "Aragon AA et al. International Society of Sports Nutrition position stand: diets and body composition. J Int Soc Sports Nutr 2017;14:16.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20."}, "blocks": [{"t": "lead", "text": "Fat loss is a slow, steady deficit with heavy training and high protein. Lose too fast and you lose muscle and strength with the fat."}, {"t": "band", "title": "Weekly weight loss", "unit": "% of body weight", "ranges": [{"from": 0, "to": 0.5, "label": "Slow and very safe", "tone": "good"}, {"from": 0.5, "to": 1.0, "label": "Target pace", "tone": "good"}, {"from": 1.0, "to": 1.5, "label": "Fast, muscle at risk", "tone": "warn"}, {"from": 1.5, "to": 2.5, "label": "Too fast", "tone": "bad"}], "source": "helms2014"}, {"t": "stats", "items": [{"value": "0.5 to 1", "unit": "% a week", "label": "weight loss keeps the most muscle", "source": "helms2014"}, {"value": "2.0", "unit": "g per kg", "label": "protein a day while dieting, the top of the ISSN range", "source": "issnprotein"}]}, {"t": "compare", "do": {"title": "Keeps muscle", "items": ["Lifting heavy 2 to 4 times a week", "Protein at every meal", "Losing about 0.35 to 0.7 kg a week if you weigh 70 kg", "7 or more hours of sleep"]}, "dont": {"title": "Costs muscle", "items": ["Crash diets and skipped meals", "Swapping lifting for only cardio", "Dropping protein to save calories"]}}, {"t": "flow", "title": "Weight not moving?", "items": [{"q": "Has the weekly average been flat for 3 weeks or more?", "yes": "Go to the next question.", "no": "Wait. Water can hide fat loss for a week or two."}, {"q": "Are you logging food honestly, including oil and snacks?", "yes": "Cut about 100 to 200 kcal a day, or add 2000 daily steps.", "no": "Track for one week first; most stalls are hidden intake."}], "note": null, "source": "aragon2017"}, {"t": "evidence", "text": "Reviews of contest preparation find slower loss rates protect lean mass, and protein above normal needs helps most when lean and in a deficit.", "source": "helms2014", "grade": "moderate"}]}'::jsonb),
(18, 'muscle-gain', 'C', 'Food and body', 'Gaining muscle and weight', 'How big a surplus to eat, how fast to gain, and why more food is not more muscle.', 3, 'Muscle is built slowly. A small surplus plus hard training adds muscle; a big surplus mostly adds fat. Weekly weight gain, beginners and intermediates % of body weight Slow, lean Target pace Mostly fat 10 to 20 % surplus above maintenance; Levlofit starts at 10% 1.6 g per kg protein a day, where extra protein stops adding muscle on average Eating more when you are never hungry Add a meal Milk and a banana, or curd and poha, between meals. Use dense foods Peanuts, a little ghee on roti, paneer, dry fruits. Drink some calories Milk, lassi or a banana shake. Weigh weekly If the trend is off pace for 3 weeks, adjust by 150 to 200 kcal a day. In a meta-analysis of 49 trials, protein beyond about 1.6 g per kg a day gave no further average gain in muscle from training. strong Lean gain Small surplus, weight up slowly Hard training 3 to 5 days a week Advanced lifters: aim for the lower end Dirty bulk Eating everything in sight Gaining over 1% a week Long fat-loss diet needed afterwards', array['Iraki J, Fitschen P, Espinar S, Helms E. Nutrition recommendations for bodybuilders in the off-season: a narrative review. Sports 2019;7(7):154.', 'Morton RW et al. A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. Br J Sports Med 2018;52(6):376-384.']::text[], '{"sources": {"iraki2019": "Iraki J, Fitschen P, Espinar S, Helms E. Nutrition recommendations for bodybuilders in the off-season: a narrative review. Sports 2019;7(7):154.", "morton2018": "Morton RW et al. A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. Br J Sports Med 2018;52(6):376-384."}, "blocks": [{"t": "lead", "text": "Muscle is built slowly. A small surplus plus hard training adds muscle; a big surplus mostly adds fat."}, {"t": "band", "title": "Weekly weight gain, beginners and intermediates", "unit": "% of body weight", "ranges": [{"from": 0, "to": 0.25, "label": "Slow, lean", "tone": "good"}, {"from": 0.25, "to": 0.5, "label": "Target pace", "tone": "good"}, {"from": 0.5, "to": 1.0, "label": "Mostly fat", "tone": "warn"}], "source": "iraki2019"}, {"t": "stats", "items": [{"value": "10 to 20", "unit": "% surplus", "label": "above maintenance; Levlofit starts at 10%", "source": "iraki2019"}, {"value": "1.6", "unit": "g per kg", "label": "protein a day, where extra protein stops adding muscle on average", "source": "morton2018"}]}, {"t": "steps", "title": "Eating more when you are never hungry", "items": [{"title": "Add a meal", "text": "Milk and a banana, or curd and poha, between meals."}, {"title": "Use dense foods", "text": "Peanuts, a little ghee on roti, paneer, dry fruits."}, {"title": "Drink some calories", "text": "Milk, lassi or a banana shake."}, {"title": "Weigh weekly", "text": "If the trend is off pace for 3 weeks, adjust by 150 to 200 kcal a day."}]}, {"t": "evidence", "text": "In a meta-analysis of 49 trials, protein beyond about 1.6 g per kg a day gave no further average gain in muscle from training.", "source": "morton2018", "grade": "strong"}, {"t": "compare", "do": {"title": "Lean gain", "items": ["Small surplus, weight up slowly", "Hard training 3 to 5 days a week", "Advanced lifters: aim for the lower end"]}, "dont": {"title": "Dirty bulk", "items": ["Eating everything in sight", "Gaining over 1% a week", "Long fat-loss diet needed afterwards"]}}]}'::jsonb),
(19, 'carbs-fibre-fats', 'C', 'Food and body', 'Carbs, fibre and fats', 'Which carbs to choose, how much fibre to aim for, and the fats to keep and to limit.', 4, 'Carbs fuel training and fats keep hormones and cells healthy. Quality matters more than cutting either one out. 25 g or more naturally occurring fibre a day 400 g or more vegetables and fruit a day 40 to 70 % of energy from carbs fits a healthy diet when quality is good Choose most days Whole wheat atta, brown rice, millets like ragi, jowar and bajra Dals, chana, rajma and sprouts Whole fruit and plenty of vegetables Nuts, seeds, mustard and groundnut oil Limit Maida, sugar, sweets and sugary drinks Vanaspati and reused frying oil (trans fats) Lots of ghee, butter and coconut oil (saturated fat) Fried snacks most days Upper limits for fat, share of daily energy % of energy All fat 30% or less Saturated fat 10% or less Trans fat 1% or less Fibre in everyday food, per 100 g raw Fibre Kala chana 25.2 g Whole moong 17.0 g Rajma 16.6 g Wheat atta 11.4 g Ragi 11.2 g Guava 8.6 g Add fibre slowly over a week or two and drink water with it, so your gut can adjust.', array['World Health Organization. Carbohydrate intake for adults and children: WHO guideline. Geneva: WHO, 2023.', 'World Health Organization. Saturated fatty acid and trans-fatty acid intake for adults and children: WHO guideline. Geneva: WHO, 2023.', 'ICMR-National Institute of Nutrition. Dietary Guidelines for Indians, 2024.', 'Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.']::text[], '{"sources": {"whocarb2023": "World Health Organization. Carbohydrate intake for adults and children: WHO guideline. Geneva: WHO, 2023.", "whofat2023": "World Health Organization. Saturated fatty acid and trans-fatty acid intake for adults and children: WHO guideline. Geneva: WHO, 2023.", "icmr2024": "ICMR-National Institute of Nutrition. Dietary Guidelines for Indians, 2024.", "ifct2017": "Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad."}, "blocks": [{"t": "lead", "text": "Carbs fuel training and fats keep hormones and cells healthy. Quality matters more than cutting either one out."}, {"t": "stats", "items": [{"value": "25", "unit": "g or more", "label": "naturally occurring fibre a day", "source": "whocarb2023"}, {"value": "400", "unit": "g or more", "label": "vegetables and fruit a day", "source": "whocarb2023"}, {"value": "40 to 70", "unit": "% of energy", "label": "from carbs fits a healthy diet when quality is good", "source": "whocarb2023"}]}, {"t": "compare", "do": {"title": "Choose most days", "items": ["Whole wheat atta, brown rice, millets like ragi, jowar and bajra", "Dals, chana, rajma and sprouts", "Whole fruit and plenty of vegetables", "Nuts, seeds, mustard and groundnut oil"]}, "dont": {"title": "Limit", "items": ["Maida, sugar, sweets and sugary drinks", "Vanaspati and reused frying oil (trans fats)", "Lots of ghee, butter and coconut oil (saturated fat)", "Fried snacks most days"]}}, {"t": "bars", "title": "Upper limits for fat, share of daily energy", "unit": "% of energy", "items": [{"label": "All fat", "value": 30, "note": "30% or less"}, {"label": "Saturated fat", "value": 10, "note": "10% or less"}, {"label": "Trans fat", "value": 1, "note": "1% or less"}], "source": "whofat2023"}, {"t": "table", "head": ["Fibre in everyday food, per 100 g raw", "Fibre"], "rows": [["Kala chana", "25.2 g"], ["Whole moong", "17.0 g"], ["Rajma", "16.6 g"], ["Wheat atta", "11.4 g"], ["Ragi", "11.2 g"], ["Guava", "8.6 g"]], "source": "ifct2017"}, {"t": "rule", "text": "Add fibre slowly over a week or two and drink water with it, so your gut can adjust."}]}'::jsonb),
(20, 'veg-protein', 'C', 'Food and body', 'Vegetarian and vegan protein', 'Hitting protein without meat: the best Indian sources, combining foods, and soya chunks.', 3, 'You can build muscle on a vegetarian or vegan diet. It takes planning: protein-dense foods at every meal and a mix of sources. 51.5 g protein in 100 g of dry soya chunks, the richest common vegetarian source Food, per 100 g raw Protein Energy Masoor dal 24.4 g 322 kcal Moong dal 23.9 g 326 kcal Peanuts 23.7 g 520 kcal Chana dal 21.6 g 329 kcal Paneer 18.9 g 258 kcal A high-protein vegetarian day Breakfast Moong chilla or besan cheela, or poha with peanuts and curd. Lunch Dal plus rajma or chana with roti; pulses and grains cover each other''s gaps. Snack Roasted chana, sprouts chaat or a glass of milk. Dinner Soya chunk curry, paneer bhurji or tofu with vegetables. Soy did not change male hormones across clinical studies, at any dose tested. strong Vegetarian staples Paneer, curd and milk Dals, chana and rajma Soya chunks Vegan staples Tofu and soya chunks Dals, chana, rajma and sprouts Peanuts; aim for the upper end of your protein range', array['Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.', 'U.S. Department of Agriculture, Agricultural Research Service. FoodData Central: Soy flour, defatted (FDC ID 174275, SR Legacy 16117).', 'Reed KE et al. Neither soy nor isoflavone intake affects male reproductive hormones: an expanded and updated meta-analysis of clinical studies. Reprod Toxicol 2021;100:60-67.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.']::text[], '{"sources": {"ifct2017": "Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.", "usda174275": "U.S. Department of Agriculture, Agricultural Research Service. FoodData Central: Soy flour, defatted (FDC ID 174275, SR Legacy 16117).", "soy2021": "Reed KE et al. Neither soy nor isoflavone intake affects male reproductive hormones: an expanded and updated meta-analysis of clinical studies. Reprod Toxicol 2021;100:60-67.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20."}, "blocks": [{"t": "lead", "text": "You can build muscle on a vegetarian or vegan diet. It takes planning: protein-dense foods at every meal and a mix of sources."}, {"t": "stats", "items": [{"value": "51.5", "unit": "g protein", "label": "in 100 g of dry soya chunks, the richest common vegetarian source", "source": "usda174275"}]}, {"t": "table", "head": ["Food, per 100 g raw", "Protein", "Energy"], "rows": [["Masoor dal", "24.4 g", "322 kcal"], ["Moong dal", "23.9 g", "326 kcal"], ["Peanuts", "23.7 g", "520 kcal"], ["Chana dal", "21.6 g", "329 kcal"], ["Paneer", "18.9 g", "258 kcal"]], "source": "ifct2017"}, {"t": "steps", "title": "A high-protein vegetarian day", "items": [{"title": "Breakfast", "text": "Moong chilla or besan cheela, or poha with peanuts and curd."}, {"title": "Lunch", "text": "Dal plus rajma or chana with roti; pulses and grains cover each other''s gaps."}, {"title": "Snack", "text": "Roasted chana, sprouts chaat or a glass of milk."}, {"title": "Dinner", "text": "Soya chunk curry, paneer bhurji or tofu with vegetables."}]}, {"t": "evidence", "text": "Soy did not change male hormones across clinical studies, at any dose tested.", "source": "soy2021", "grade": "strong"}, {"t": "compare", "do": {"title": "Vegetarian staples", "items": ["Paneer, curd and milk", "Dals, chana and rajma", "Soya chunks"]}, "dont": {"title": "Vegan staples", "items": ["Tofu and soya chunks", "Dals, chana, rajma and sprouts", "Peanuts; aim for the upper end of your protein range"]}}]}'::jsonb),
(21, 'meal-timing', 'C', 'Food and body', 'When to eat around training', 'What matters about meal timing, and what does not.', 3, 'Total daily food matters most. Timing is fine-tuning: spread protein through the day and do not train on an empty tank. What matters most 1 Total calories Sets whether you gain, lose or hold weight. 2 Total protein Drives muscle repair across the day. 3 Protein spread 20 to 40 g every 3 to 4 hours. 4 Meals around training Helps how you feel and recover. 5 Exact minutes Barely matters for most people. Around a session 2 to 3 h before A normal meal: roti or rice, dal or paneer, vegetables. 30 to 60 min before If hungry: a banana or a small bowl of poha. Within a few hours after A protein-rich meal; no need to rush a shake. 20 to 40 g protein per meal, every 3 to 4 hours When daily protein and energy are met, the exact timing after a session matters little for most people; it matters more for long or twice-daily sessions. moderate', array['Kerksick CM et al. International Society of Sports Nutrition position stand: nutrient timing. J Int Soc Sports Nutr 2017;14:33.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.']::text[], '{"sources": {"kerksick2017": "Kerksick CM et al. International Society of Sports Nutrition position stand: nutrient timing. J Int Soc Sports Nutr 2017;14:33.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20."}, "blocks": [{"t": "lead", "text": "Total daily food matters most. Timing is fine-tuning: spread protein through the day and do not train on an empty tank."}, {"t": "scale", "title": "What matters most", "items": [{"mark": "1", "label": "Total calories", "text": "Sets whether you gain, lose or hold weight."}, {"mark": "2", "label": "Total protein", "text": "Drives muscle repair across the day."}, {"mark": "3", "label": "Protein spread", "text": "20 to 40 g every 3 to 4 hours."}, {"mark": "4", "label": "Meals around training", "text": "Helps how you feel and recover."}, {"mark": "5", "label": "Exact minutes", "text": "Barely matters for most people."}], "source": "kerksick2017"}, {"t": "steps", "title": "Around a session", "items": [{"title": "2 to 3 h before", "text": "A normal meal: roti or rice, dal or paneer, vegetables."}, {"title": "30 to 60 min before", "text": "If hungry: a banana or a small bowl of poha."}, {"title": "Within a few hours after", "text": "A protein-rich meal; no need to rush a shake."}]}, {"t": "stats", "items": [{"value": "20 to 40", "unit": "g", "label": "protein per meal, every 3 to 4 hours", "source": "issnprotein"}]}, {"t": "evidence", "text": "When daily protein and energy are met, the exact timing after a session matters little for most people; it matters more for long or twice-daily sessions.", "source": "kerksick2017", "grade": "moderate"}]}'::jsonb),
(22, 'build-muscle', 'D', 'Train for your goal', 'Building muscle', 'How many sets per muscle, how heavy, and how close to failure to grow.', 4, 'Muscle grows from enough hard sets per muscle each week, repeated for months. Load can vary; effort and consistency cannot. Weekly sets per muscle and growth sets a week Under 5 sets least growth 5 to 9 sets more 10 or more sets most 10+ sets per muscle a week gave the most growth Light or heavy  loads both build muscle when sets end close to failure Example: 4-day upper and lower Mon Upper Tue Lower Wed Walk Thu Upper Fri Lower Sat Mobility Sun Rest Grows muscle Sets ending 1 to 3 reps from failure Adding reps or weight over time Training each muscle twice a week Wastes effort Easy sets far from failure Changing exercises every week Endless sets with poor form Low and high loads built similar muscle when sets went close to failure; heavier loads built more maximal strength. strong', array['Schoenfeld BJ, Ogborn D, Krieger JW. Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. J Sports Sci 2017;35(11):1073-1082.', 'Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res 2017;31(12):3508-3523.']::text[], '{"sources": {"schoenfeld2017v": "Schoenfeld BJ, Ogborn D, Krieger JW. Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. J Sports Sci 2017;35(11):1073-1082.", "schoenfeld2017l": "Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res 2017;31(12):3508-3523."}, "blocks": [{"t": "lead", "text": "Muscle grows from enough hard sets per muscle each week, repeated for months. Load can vary; effort and consistency cannot."}, {"t": "bars", "title": "Weekly sets per muscle and growth", "unit": "sets a week", "items": [{"label": "Under 5 sets", "value": 4, "note": "least growth"}, {"label": "5 to 9 sets", "value": 7, "note": "more"}, {"label": "10 or more sets", "value": 10, "note": "most"}], "source": "schoenfeld2017v"}, {"t": "stats", "items": [{"value": "10+", "unit": "sets", "label": "per muscle a week gave the most growth", "source": "schoenfeld2017v"}, {"value": "Light or heavy", "unit": "", "label": "loads both build muscle when sets end close to failure", "source": "schoenfeld2017l"}]}, {"t": "week", "title": "Example: 4-day upper and lower", "days": [{"day": "Mon", "label": "Upper", "kind": "strength"}, {"day": "Tue", "label": "Lower", "kind": "strength"}, {"day": "Wed", "label": "Walk", "kind": "cardio"}, {"day": "Thu", "label": "Upper", "kind": "strength"}, {"day": "Fri", "label": "Lower", "kind": "strength"}, {"day": "Sat", "label": "Mobility", "kind": "mobility"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "compare", "do": {"title": "Grows muscle", "items": ["Sets ending 1 to 3 reps from failure", "Adding reps or weight over time", "Training each muscle twice a week"]}, "dont": {"title": "Wastes effort", "items": ["Easy sets far from failure", "Changing exercises every week", "Endless sets with poor form"]}}, {"t": "evidence", "text": "Low and high loads built similar muscle when sets went close to failure; heavier loads built more maximal strength.", "source": "schoenfeld2017l", "grade": "strong"}]}'::jsonb),
(23, 'get-stronger', 'D', 'Train for your goal', 'Getting stronger and powerlifting', 'Heavy, practised lifts: squat, bench and deadlift, and how strength is built.', 4, 'Strength is a skill as well as muscle. Lift heavy, practise the same lifts often, and rest long enough to lift well. Heavy loads build more maximal strength than light loads 2+ min rest between heavy sets helps strength Lift What it trains Key cue Squat Legs, hips, trunk Brace, knees track over toes Bench press Chest, shoulders, triceps Shoulder blades pinned, feet planted Deadlift Back, hips, grip Bar close, back flat, push the floor away Overhead press Shoulders, triceps Glutes tight, bar over mid-foot Effort for strength work, reps in reserve RIR 4+ Technique Warm-up and practice sets. RIR 2 to 3 Most work sets Bar speed stays good. RIR 0 to 1 Rarely Tests and the last set of a block. A strength block Weeks 1 to 3 Build: add 2.5 to 5 kg when every rep is clean. Week 4 A lighter week to recover. Then Retest, or start the next block a little heavier. Powerlifting meets need a coach for technique and peaking. Levlofit''s Strength path builds the base.', array['Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res 2017;31(12):3508-3523.', 'Grgic J, Schoenfeld BJ, Skrepnik M, Davies TB, Mikulic P. Effects of rest interval duration in resistance training on measures of muscular strength: a systematic review. Sports Med 2018;48(1):137-151.', 'Zourdos MC et al. Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. J Strength Cond Res 2016;30(1):267-275.']::text[], '{"sources": {"schoenfeld2017l": "Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res 2017;31(12):3508-3523.", "grgic2018": "Grgic J, Schoenfeld BJ, Skrepnik M, Davies TB, Mikulic P. Effects of rest interval duration in resistance training on measures of muscular strength: a systematic review. Sports Med 2018;48(1):137-151.", "zourdos2016": "Zourdos MC et al. Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. J Strength Cond Res 2016;30(1):267-275."}, "blocks": [{"t": "lead", "text": "Strength is a skill as well as muscle. Lift heavy, practise the same lifts often, and rest long enough to lift well."}, {"t": "stats", "items": [{"value": "Heavy", "unit": "loads", "label": "build more maximal strength than light loads", "source": "schoenfeld2017l"}, {"value": "2+", "unit": "min rest", "label": "between heavy sets helps strength", "source": "grgic2018"}]}, {"t": "table", "head": ["Lift", "What it trains", "Key cue"], "rows": [["Squat", "Legs, hips, trunk", "Brace, knees track over toes"], ["Bench press", "Chest, shoulders, triceps", "Shoulder blades pinned, feet planted"], ["Deadlift", "Back, hips, grip", "Bar close, back flat, push the floor away"], ["Overhead press", "Shoulders, triceps", "Glutes tight, bar over mid-foot"]], "source": null}, {"t": "scale", "title": "Effort for strength work, reps in reserve", "items": [{"mark": "RIR 4+", "label": "Technique", "text": "Warm-up and practice sets."}, {"mark": "RIR 2 to 3", "label": "Most work sets", "text": "Bar speed stays good."}, {"mark": "RIR 0 to 1", "label": "Rarely", "text": "Tests and the last set of a block."}], "source": "zourdos2016"}, {"t": "steps", "title": "A strength block", "items": [{"title": "Weeks 1 to 3", "text": "Build: add 2.5 to 5 kg when every rep is clean."}, {"title": "Week 4", "text": "A lighter week to recover."}, {"title": "Then", "text": "Retest, or start the next block a little heavier."}]}, {"t": "rule", "text": "Powerlifting meets need a coach for technique and peaking. Levlofit''s Strength path builds the base."}]}'::jsonb),
(24, 'physique', 'D', 'Train for your goal', 'Building an aesthetic physique', 'Proportions, which muscles shape the look, and pairing training with body-fat changes.', 3, 'An aesthetic look is muscle in the right places plus low enough body fat to see it. Build first, then lean out. Area Why it matters Key moves Side delts Width, V-taper Lateral raise, overhead press Upper back, lats Width and posture Pull-up, lat pulldown, rows Upper chest A fuller chest Incline press Arms Proportion Curls, pushdowns, dips Legs Balance with the upper body Squat, lunge, Romanian deadlift The physique year Build muscle Lean out Maintain Build again 10+ sets per muscle a week for lagging areas 0.5 to 1 % a week loss pace when leaning out Helps the look Extra sets for lagging muscles Patience: months, not weeks Photos and tape every 2 to 4 weeks Hurts it Only training mirror muscles Skipping legs Cutting before you have built muscle', array['Schoenfeld BJ, Ogborn D, Krieger JW. Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. J Sports Sci 2017;35(11):1073-1082.', 'Helms ER, Aragon AA, Fitschen PJ. Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. J Int Soc Sports Nutr 2014;11:20.']::text[], '{"sources": {"schoenfeld2017v": "Schoenfeld BJ, Ogborn D, Krieger JW. Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. J Sports Sci 2017;35(11):1073-1082.", "helms2014": "Helms ER, Aragon AA, Fitschen PJ. Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. J Int Soc Sports Nutr 2014;11:20."}, "blocks": [{"t": "lead", "text": "An aesthetic look is muscle in the right places plus low enough body fat to see it. Build first, then lean out."}, {"t": "table", "head": ["Area", "Why it matters", "Key moves"], "rows": [["Side delts", "Width, V-taper", "Lateral raise, overhead press"], ["Upper back, lats", "Width and posture", "Pull-up, lat pulldown, rows"], ["Upper chest", "A fuller chest", "Incline press"], ["Arms", "Proportion", "Curls, pushdowns, dips"], ["Legs", "Balance with the upper body", "Squat, lunge, Romanian deadlift"]], "source": null}, {"t": "cycle", "title": "The physique year", "items": ["Build muscle", "Lean out", "Maintain", "Build again"]}, {"t": "stats", "items": [{"value": "10+", "unit": "sets", "label": "per muscle a week for lagging areas", "source": "schoenfeld2017v"}, {"value": "0.5 to 1", "unit": "% a week", "label": "loss pace when leaning out", "source": "helms2014"}]}, {"t": "compare", "do": {"title": "Helps the look", "items": ["Extra sets for lagging muscles", "Patience: months, not weeks", "Photos and tape every 2 to 4 weeks"]}, "dont": {"title": "Hurts it", "items": ["Only training mirror muscles", "Skipping legs", "Cutting before you have built muscle"]}}]}'::jsonb),
(25, 'calisthenics', 'D', 'Train for your goal', 'Calisthenics', 'Bodyweight strength: progressions from push-ups to pull-ups, dips and holds.', 4, 'Your body is the barbell. You progress by making the move harder: more leverage, fewer points of support, more range. Skill Start Next Goal Push Incline push-up Full push-up Archer, then one-arm push-up Pull Inverted row Negative pull-up Strict pull-ups, then weighted Squat Box squat Split squat Pistol squat Hold Plank Hollow hold L-sit Dip Bench dip Negative dip Parallel bar dips How to move up a step Hit the target 3 sets of 8 to 12 clean reps, or 3 holds of 30 s. Step up Move to the next variation, even if reps drop to 3 to 5. Build again Climb back to the target, then step up again. Similar  strength and muscle gains from progressive push-ups as from bench press A controlled trial found progressive push-ups matched the bench press for strength and muscle thickness gains. moderate Your first pull-up Inverted rows Band-assisted pull-ups Slow negatives First strict pull-up', array['Kotarsky CJ et al. Effect of progressive calisthenic push-up training on muscle strength and thickness. J Strength Cond Res 2018;32(3):651-659.']::text[], '{"sources": {"kotarsky2018": "Kotarsky CJ et al. Effect of progressive calisthenic push-up training on muscle strength and thickness. J Strength Cond Res 2018;32(3):651-659."}, "blocks": [{"t": "lead", "text": "Your body is the barbell. You progress by making the move harder: more leverage, fewer points of support, more range."}, {"t": "table", "head": ["Skill", "Start", "Next", "Goal"], "rows": [["Push", "Incline push-up", "Full push-up", "Archer, then one-arm push-up"], ["Pull", "Inverted row", "Negative pull-up", "Strict pull-ups, then weighted"], ["Squat", "Box squat", "Split squat", "Pistol squat"], ["Hold", "Plank", "Hollow hold", "L-sit"], ["Dip", "Bench dip", "Negative dip", "Parallel bar dips"]], "source": null}, {"t": "steps", "title": "How to move up a step", "items": [{"title": "Hit the target", "text": "3 sets of 8 to 12 clean reps, or 3 holds of 30 s."}, {"title": "Step up", "text": "Move to the next variation, even if reps drop to 3 to 5."}, {"title": "Build again", "text": "Climb back to the target, then step up again."}]}, {"t": "stats", "items": [{"value": "Similar", "unit": "", "label": "strength and muscle gains from progressive push-ups as from bench press", "source": "kotarsky2018"}]}, {"t": "evidence", "text": "A controlled trial found progressive push-ups matched the bench press for strength and muscle thickness gains.", "source": "kotarsky2018", "grade": "moderate"}, {"t": "cycle", "title": "Your first pull-up", "items": ["Inverted rows", "Band-assisted pull-ups", "Slow negatives", "First strict pull-up"]}]}'::jsonb),
(26, 'running', 'D', 'Train for your goal', 'Running', 'Easy miles, safe weekly increases, and the 80/20 way to run faster.', 4, 'Most of your running should feel easy. You get faster by running more, gradually, with a little hard work on top. How endurance athletes mix intensity Easy, can talk in sentences about 80% Hard, intervals or tempo about 20% Weekly distance increase, new runners % more than last week Safer Watch for niggles Higher injury risk From zero to 5 km Weeks 1 to 2 Run 1 min, walk 2 min, 8 rounds, 3 days a week. Weeks 3 to 5 Run 3 to 5 min, walk 1 to 2 min. Weeks 6 to 8 Run 10 to 20 min without stopping. Week 9 on Run 5 km easy, then add one faster session a week. The talk test Easy Full sentences Most runs. Steady Short phrases Tempo runs. Hard A few words Intervals only. Novice runners who raised weekly distance by more than 30% over two weeks had more overuse injuries than those who added under 10%. moderate', array['Seiler S. What is best practice for training intensity and duration distribution in endurance athletes? Int J Sports Physiol Perform 2010;5(3):276-291.', 'Nielsen RO et al. Excessive progression in weekly running distance and risk of running-related injuries: an association which varies according to type of injury. J Orthop Sports Phys Ther 2014;44(10):739-747.']::text[], '{"sources": {"seiler2010": "Seiler S. What is best practice for training intensity and duration distribution in endurance athletes? Int J Sports Physiol Perform 2010;5(3):276-291.", "nielsen2014": "Nielsen RO et al. Excessive progression in weekly running distance and risk of running-related injuries: an association which varies according to type of injury. J Orthop Sports Phys Ther 2014;44(10):739-747."}, "blocks": [{"t": "lead", "text": "Most of your running should feel easy. You get faster by running more, gradually, with a little hard work on top."}, {"t": "plate", "title": "How endurance athletes mix intensity", "items": [{"label": "Easy, can talk in sentences", "share": 80, "note": "about 80%"}, {"label": "Hard, intervals or tempo", "share": 20, "note": "about 20%"}], "source": "seiler2010"}, {"t": "band", "title": "Weekly distance increase, new runners", "unit": "% more than last week", "ranges": [{"from": 0, "to": 10, "label": "Safer", "tone": "good"}, {"from": 10, "to": 30, "label": "Watch for niggles", "tone": "warn"}, {"from": 30, "to": 50, "label": "Higher injury risk", "tone": "bad"}], "source": "nielsen2014"}, {"t": "steps", "title": "From zero to 5 km", "items": [{"title": "Weeks 1 to 2", "text": "Run 1 min, walk 2 min, 8 rounds, 3 days a week."}, {"title": "Weeks 3 to 5", "text": "Run 3 to 5 min, walk 1 to 2 min."}, {"title": "Weeks 6 to 8", "text": "Run 10 to 20 min without stopping."}, {"title": "Week 9 on", "text": "Run 5 km easy, then add one faster session a week."}]}, {"t": "scale", "title": "The talk test", "items": [{"mark": "Easy", "label": "Full sentences", "text": "Most runs."}, {"mark": "Steady", "label": "Short phrases", "text": "Tempo runs."}, {"mark": "Hard", "label": "A few words", "text": "Intervals only."}], "source": "seiler2010"}, {"t": "evidence", "text": "Novice runners who raised weekly distance by more than 30% over two weeks had more overuse injuries than those who added under 10%.", "source": "nielsen2014", "grade": "moderate"}]}'::jsonb),
(27, 'hyrox', 'D', 'Train for your goal', 'HYROX and functional fitness', 'The race format, the eight stations, and how to train running and strength together.', 4, 'HYROX is 8 km of running split by 8 workout stations. It rewards a strong engine and strength that holds up while tired. Station, after each 1 km run Standard 1. SkiErg 1000 m 2. Sled push 50 m 3. Sled pull 50 m 4. Burpee broad jumps 80 m 5. Rowing 1000 m 6. Farmers carry 200 m 7. Sandbag lunges 100 m 8. Wall balls 100 reps Example HYROX week Mon Strength Tue Easy run Wed Stations Thu Rest Fri Intervals Sat Race sim Sun Mobility Race smart Run the first km easier than you want Practise wall balls and lunges when tired Pace the sleds; walk them if needed Common mistakes Sprinting the first run Only running, no station practice Skipping strength work Running and lifting in one plan works; keeping hard runs and leg sessions apart limits interference with strength. moderate', array['HYROX. Official rulebook, race format and station standards. hyrox.com.', 'Wilson JM et al. Concurrent training: a meta-analysis examining interference of aerobic and resistance exercises. J Strength Cond Res 2012;26(8):2293-2307.']::text[], '{"sources": {"hyrox": "HYROX. Official rulebook, race format and station standards. hyrox.com.", "wilson2012": "Wilson JM et al. Concurrent training: a meta-analysis examining interference of aerobic and resistance exercises. J Strength Cond Res 2012;26(8):2293-2307."}, "blocks": [{"t": "lead", "text": "HYROX is 8 km of running split by 8 workout stations. It rewards a strong engine and strength that holds up while tired."}, {"t": "table", "head": ["Station, after each 1 km run", "Standard"], "rows": [["1. SkiErg", "1000 m"], ["2. Sled push", "50 m"], ["3. Sled pull", "50 m"], ["4. Burpee broad jumps", "80 m"], ["5. Rowing", "1000 m"], ["6. Farmers carry", "200 m"], ["7. Sandbag lunges", "100 m"], ["8. Wall balls", "100 reps"]], "source": "hyrox"}, {"t": "week", "title": "Example HYROX week", "days": [{"day": "Mon", "label": "Strength", "kind": "strength"}, {"day": "Tue", "label": "Easy run", "kind": "cardio"}, {"day": "Wed", "label": "Stations", "kind": "strength"}, {"day": "Thu", "label": "Rest", "kind": "rest"}, {"day": "Fri", "label": "Intervals", "kind": "cardio"}, {"day": "Sat", "label": "Race sim", "kind": "cardio"}, {"day": "Sun", "label": "Mobility", "kind": "mobility"}]}, {"t": "compare", "do": {"title": "Race smart", "items": ["Run the first km easier than you want", "Practise wall balls and lunges when tired", "Pace the sleds; walk them if needed"]}, "dont": {"title": "Common mistakes", "items": ["Sprinting the first run", "Only running, no station practice", "Skipping strength work"]}}, {"t": "evidence", "text": "Running and lifting in one plan works; keeping hard runs and leg sessions apart limits interference with strength.", "source": "wilson2012", "grade": "moderate"}]}'::jsonb),
(28, 'mobility', 'D', 'Train for your goal', 'Mobility and yoga', 'How to gain range of motion, when to stretch, and what yoga adds.', 3, 'Range of motion improves with regular practice. Stretching works, and so does strength training through a full range. Same  range of motion gains from full-range strength training as from stretching Builds mobility Full-range lifts: deep squats, RDLs, full push-ups Holding stretches 30 to 60 s, most days Yoga 2 to 3 times a week Does little Stretching only once a week Forcing into pain Bouncing in a stretch 10-minute daily routine Hips Deep squat hold, 60 s. Hamstrings Standing forward fold, 60 s. Upper back Thread the needle, 5 each side. Shoulders Wall slides, 10. Ankles Knee-to-wall, 10 each side. Static stretches under 60 s before training barely affect strength; long holds right before heavy lifting can reduce force a little. strong Practice Best for Yoga Mobility, balance, calm Yoga flow in Levlofit Sphinx, butterfly, frog and twists Full-range lifting Strength and range together', array['Afonso J et al. Strength training versus stretching for improving range of motion: a systematic review and meta-analysis. Healthcare 2021;9(4):427.', 'Behm DG et al. Acute effects of muscle stretching on physical performance, range of motion, and injury incidence in healthy active individuals: a systematic review. Appl Physiol Nutr Metab 2016;41(1):1-11.']::text[], '{"sources": {"afonso2021": "Afonso J et al. Strength training versus stretching for improving range of motion: a systematic review and meta-analysis. Healthcare 2021;9(4):427.", "behm2016": "Behm DG et al. Acute effects of muscle stretching on physical performance, range of motion, and injury incidence in healthy active individuals: a systematic review. Appl Physiol Nutr Metab 2016;41(1):1-11."}, "blocks": [{"t": "lead", "text": "Range of motion improves with regular practice. Stretching works, and so does strength training through a full range."}, {"t": "stats", "items": [{"value": "Same", "unit": "", "label": "range of motion gains from full-range strength training as from stretching", "source": "afonso2021"}]}, {"t": "compare", "do": {"title": "Builds mobility", "items": ["Full-range lifts: deep squats, RDLs, full push-ups", "Holding stretches 30 to 60 s, most days", "Yoga 2 to 3 times a week"]}, "dont": {"title": "Does little", "items": ["Stretching only once a week", "Forcing into pain", "Bouncing in a stretch"]}}, {"t": "steps", "title": "10-minute daily routine", "items": [{"title": "Hips", "text": "Deep squat hold, 60 s."}, {"title": "Hamstrings", "text": "Standing forward fold, 60 s."}, {"title": "Upper back", "text": "Thread the needle, 5 each side."}, {"title": "Shoulders", "text": "Wall slides, 10."}, {"title": "Ankles", "text": "Knee-to-wall, 10 each side."}]}, {"t": "evidence", "text": "Static stretches under 60 s before training barely affect strength; long holds right before heavy lifting can reduce force a little.", "source": "behm2016", "grade": "strong"}, {"t": "table", "head": ["Practice", "Best for"], "rows": [["Yoga", "Mobility, balance, calm"], ["Yoga flow in Levlofit", "Sphinx, butterfly, frog and twists"], ["Full-range lifting", "Strength and range together"]], "source": null}]}'::jsonb),
(29, 'kettlebells', 'D', 'Train for your goal', 'Kettlebell training', 'Swings, goblet squats and carries: big results from one bell.', 3, 'One kettlebell trains strength, power and conditioning. The swing is the centre of it all. Move Trains Start with Swing Hips, back, power, heart 3 x 10 Goblet squat Legs, trunk 3 x 8 Press Shoulders 3 x 5 each arm Row Back, grip 3 x 8 each arm Farmers carry Grip, trunk 3 x 30 m The swing Hinge Hips back, flat back, bell between the forearms. Snap Drive the hips forward hard, glutes tight. Float Arms only guide; the bell rises to chest height. Return Let it fall, then hinge again. 6 weeks of swings improved maximal and explosive strength Reviews find kettlebell training improves strength and fitness, but most studies are small. moderate', array['Lake JP, Lauder MA. Kettlebell swing training improves maximal and explosive strength. J Strength Cond Res 2012;26(8):2228-2233.', 'Meigh NJ et al. Kettlebell training in clinical practice: a scoping review. BMC Sports Sci Med Rehabil 2019;11:19.']::text[], '{"sources": {"lake2012": "Lake JP, Lauder MA. Kettlebell swing training improves maximal and explosive strength. J Strength Cond Res 2012;26(8):2228-2233.", "meigh2019": "Meigh NJ et al. Kettlebell training in clinical practice: a scoping review. BMC Sports Sci Med Rehabil 2019;11:19."}, "blocks": [{"t": "lead", "text": "One kettlebell trains strength, power and conditioning. The swing is the centre of it all."}, {"t": "table", "head": ["Move", "Trains", "Start with"], "rows": [["Swing", "Hips, back, power, heart", "3 x 10"], ["Goblet squat", "Legs, trunk", "3 x 8"], ["Press", "Shoulders", "3 x 5 each arm"], ["Row", "Back, grip", "3 x 8 each arm"], ["Farmers carry", "Grip, trunk", "3 x 30 m"]], "source": null}, {"t": "steps", "title": "The swing", "items": [{"title": "Hinge", "text": "Hips back, flat back, bell between the forearms."}, {"title": "Snap", "text": "Drive the hips forward hard, glutes tight."}, {"title": "Float", "text": "Arms only guide; the bell rises to chest height."}, {"title": "Return", "text": "Let it fall, then hinge again."}]}, {"t": "stats", "items": [{"value": "6", "unit": "weeks", "label": "of swings improved maximal and explosive strength", "source": "lake2012"}]}, {"t": "evidence", "text": "Reviews find kettlebell training improves strength and fitness, but most studies are small.", "source": "meigh2019", "grade": "moderate"}]}'::jsonb),
(30, 'general-fitness', 'D', 'Train for your goal', 'General fitness and heart health', 'The mix of cardio, strength and movement that keeps you healthy for life.', 3, 'For lifelong health, do some of everything: lift twice a week, move your heart most days, and sit less. A balanced week Mon Full body Tue Brisk walk Wed Cycle or swim Thu Full body Fri Walk Sat Sport or yoga Sun Rest 150 to 300 min of moderate cardio a week 2 days of strength training a week About 5x  higher risk of death with the lowest fitness versus the highest Builds heart fitness Brisk walking, cycling, swimming Sports and games Stairs instead of the lift Easy to forget Long sitting without breaks Only lifting, no cardio In 122,007 adults, low cardiorespiratory fitness carried a mortality risk as large as smoking or diabetes, with no upper limit of benefit. strong', array['Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.', 'Mandsager K et al. Association of cardiorespiratory fitness with long-term mortality among adults undergoing exercise treadmill testing. JAMA Netw Open 2018;1(6):e183605.']::text[], '{"sources": {"who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.", "mandsager2018": "Mandsager K et al. Association of cardiorespiratory fitness with long-term mortality among adults undergoing exercise treadmill testing. JAMA Netw Open 2018;1(6):e183605."}, "blocks": [{"t": "lead", "text": "For lifelong health, do some of everything: lift twice a week, move your heart most days, and sit less."}, {"t": "week", "title": "A balanced week", "days": [{"day": "Mon", "label": "Full body", "kind": "strength"}, {"day": "Tue", "label": "Brisk walk", "kind": "cardio"}, {"day": "Wed", "label": "Cycle or swim", "kind": "cardio"}, {"day": "Thu", "label": "Full body", "kind": "strength"}, {"day": "Fri", "label": "Walk", "kind": "cardio"}, {"day": "Sat", "label": "Sport or yoga", "kind": "mobility"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "stats", "items": [{"value": "150 to 300", "unit": "min", "label": "of moderate cardio a week", "source": "who2020"}, {"value": "2", "unit": "days", "label": "of strength training a week", "source": "who2020"}, {"value": "About 5x", "unit": "", "label": "higher risk of death with the lowest fitness versus the highest", "source": "mandsager2018"}]}, {"t": "compare", "do": {"title": "Builds heart fitness", "items": ["Brisk walking, cycling, swimming", "Sports and games", "Stairs instead of the lift"]}, "dont": {"title": "Easy to forget", "items": ["Long sitting without breaks", "Only lifting, no cardio"]}}, {"t": "evidence", "text": "In 122,007 adults, low cardiorespiratory fitness carried a mortality risk as large as smoking or diabetes, with no upper limit of benefit.", "source": "mandsager2018", "grade": "strong"}]}'::jsonb),
(31, 'soreness-pain-injury', 'E', 'Staying with it', 'Soreness, pain and injuries', 'Normal soreness versus pain that needs care, and how training prevents injury.', 3, 'Soreness after a new workout is normal. Sharp, joint or worsening pain is not. Strength training is one of the best ways to prevent injuries. Normal soreness Dull ache in the muscle, 1 to 3 days after Both sides feel the same Eases as you warm up Pain to respect Sharp or stabbing, in a joint Swelling, or a joint giving way Gets worse during the session Lasts more than a week Pain during exercise, a common physio guide pain out of 10 OK to train Reduce load or range Stop, see a physio or doctor Under 1/3  of sports injuries remained with strength training Coming back from a niggle Calm it Swap to pain-free moves for a few days; keep moving. Reload Return at about half the weight; add a little each session. Rebuild Back to full once it stays pain-free the next day. Across 25 trials, strength training cut sports injuries to under a third, while stretching alone did not prevent injury. strong', array['Lauersen JB, Bertelsen DM, Andersen LB. The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. Br J Sports Med 2014;48(11):871-877.']::text[], '{"sources": {"lauersen2014": "Lauersen JB, Bertelsen DM, Andersen LB. The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. Br J Sports Med 2014;48(11):871-877."}, "blocks": [{"t": "lead", "text": "Soreness after a new workout is normal. Sharp, joint or worsening pain is not. Strength training is one of the best ways to prevent injuries."}, {"t": "compare", "do": {"title": "Normal soreness", "items": ["Dull ache in the muscle, 1 to 3 days after", "Both sides feel the same", "Eases as you warm up"]}, "dont": {"title": "Pain to respect", "items": ["Sharp or stabbing, in a joint", "Swelling, or a joint giving way", "Gets worse during the session", "Lasts more than a week"]}}, {"t": "band", "title": "Pain during exercise, a common physio guide", "unit": "pain out of 10", "ranges": [{"from": 0, "to": 3, "label": "OK to train", "tone": "good"}, {"from": 3, "to": 5, "label": "Reduce load or range", "tone": "warn"}, {"from": 5, "to": 10, "label": "Stop, see a physio or doctor", "tone": "bad"}], "source": null}, {"t": "stats", "items": [{"value": "Under 1/3", "unit": "", "label": "of sports injuries remained with strength training", "source": "lauersen2014"}]}, {"t": "steps", "title": "Coming back from a niggle", "items": [{"title": "Calm it", "text": "Swap to pain-free moves for a few days; keep moving."}, {"title": "Reload", "text": "Return at about half the weight; add a little each session."}, {"title": "Rebuild", "text": "Back to full once it stays pain-free the next day."}]}, {"t": "evidence", "text": "Across 25 trials, strength training cut sports injuries to under a third, while stretching alone did not prevent injury.", "source": "lauersen2014", "grade": "strong"}]}'::jsonb),
(32, 'plateaus-deloads', 'E', 'Staying with it', 'Plateaus and lighter weeks', 'Why progress stalls, how to break through, and when to take a deload week.', 3, 'Every lifter stalls. Usually the fix is recovery, food or a small change in the plan, not a whole new program. Stuck for 3 weeks or more? Are you sleeping under 7 hours, or eating in a deficit? Fix sleep and food first; progress slows when recovery is short. Go to the next question. Have you trained hard for many weeks without a lighter week? Take a deload week. Go to the next question. Same exercises and reps for months? Change the rep range or swap one exercise per muscle. Add one set per muscle a week. A deload week Same lifts Keep the exercises. Less work Cut sets by about half, or use lighter weights. Easy effort Stop sets well before failure. Come back Return to normal training the week after. A training block Build for several weeks Deload Start a little stronger Coaches agree deloads lower fatigue and support long-term progress; timing is set by how you feel and perform, not a fixed calendar. consensus', array['Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87.']::text[], '{"sources": {"bell2023": "Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87."}, "blocks": [{"t": "lead", "text": "Every lifter stalls. Usually the fix is recovery, food or a small change in the plan, not a whole new program."}, {"t": "flow", "title": "Stuck for 3 weeks or more?", "items": [{"q": "Are you sleeping under 7 hours, or eating in a deficit?", "yes": "Fix sleep and food first; progress slows when recovery is short.", "no": "Go to the next question."}, {"q": "Have you trained hard for many weeks without a lighter week?", "yes": "Take a deload week.", "no": "Go to the next question."}, {"q": "Same exercises and reps for months?", "yes": "Change the rep range or swap one exercise per muscle.", "no": "Add one set per muscle a week."}], "note": null, "source": "bell2023"}, {"t": "steps", "title": "A deload week", "items": [{"title": "Same lifts", "text": "Keep the exercises."}, {"title": "Less work", "text": "Cut sets by about half, or use lighter weights."}, {"title": "Easy effort", "text": "Stop sets well before failure."}, {"title": "Come back", "text": "Return to normal training the week after."}]}, {"t": "cycle", "title": "A training block", "items": ["Build for several weeks", "Deload", "Start a little stronger"]}, {"t": "evidence", "text": "Coaches agree deloads lower fatigue and support long-term progress; timing is set by how you feel and perform, not a fixed calendar.", "source": "bell2023", "grade": "consensus"}]}'::jsonb),
(33, 'busy-weeks', 'E', 'Staying with it', 'Missed sessions, travel and busy weeks', 'How little training keeps your progress, and what to do when life gets in the way.', 3, 'Missing a week does not erase months of work. A little training keeps most of what you built. 1/3  of the usual training dose kept muscle size in young adults over 32 weeks Missed sessions? Missed one session? Carry on with the next one. Do not double up. Go to the next question. Missed a week or more? Restart at about 80% of your last weights for one week. Carry on as planned. 20-minute hotel room workout Squats 3 x 15 to 20. Push-ups 3 sets close to failure. Backpack rows 3 x 12 each arm, bag filled with books. Lunges 3 x 10 each leg. Plank 3 x 30 to 45 s. Busy-week rules Keep 1 or 2 short full-body sessions Walk more: calls on foot, stairs Protect sleep Avoid All-or-nothing thinking Making up missed sessions in one day In a 32-week trial, one-third of the training dose kept muscle size in young adults; older adults needed more to keep size, though their strength held well. moderate', array['Bickel CS, Cross JM, Bamman MM. Exercise dosing to retain resistance training adaptations in young and older adults. Med Sci Sports Exerc 2011;43(7):1177-1187.']::text[], '{"sources": {"bickel2011": "Bickel CS, Cross JM, Bamman MM. Exercise dosing to retain resistance training adaptations in young and older adults. Med Sci Sports Exerc 2011;43(7):1177-1187."}, "blocks": [{"t": "lead", "text": "Missing a week does not erase months of work. A little training keeps most of what you built."}, {"t": "stats", "items": [{"value": "1/3", "unit": "", "label": "of the usual training dose kept muscle size in young adults over 32 weeks", "source": "bickel2011"}]}, {"t": "flow", "title": "Missed sessions?", "items": [{"q": "Missed one session?", "yes": "Carry on with the next one. Do not double up.", "no": "Go to the next question."}, {"q": "Missed a week or more?", "yes": "Restart at about 80% of your last weights for one week.", "no": "Carry on as planned."}], "note": null, "source": null}, {"t": "steps", "title": "20-minute hotel room workout", "items": [{"title": "Squats", "text": "3 x 15 to 20."}, {"title": "Push-ups", "text": "3 sets close to failure."}, {"title": "Backpack rows", "text": "3 x 12 each arm, bag filled with books."}, {"title": "Lunges", "text": "3 x 10 each leg."}, {"title": "Plank", "text": "3 x 30 to 45 s."}]}, {"t": "compare", "do": {"title": "Busy-week rules", "items": ["Keep 1 or 2 short full-body sessions", "Walk more: calls on foot, stairs", "Protect sleep"]}, "dont": {"title": "Avoid", "items": ["All-or-nothing thinking", "Making up missed sessions in one day"]}}, {"t": "evidence", "text": "In a 32-week trial, one-third of the training dose kept muscle size in young adults; older adults needed more to keep size, though their strength held well.", "source": "bickel2011", "grade": "moderate"}]}'::jsonb),
(34, 'home-training', 'E', 'Staying with it', 'Training at home', 'Building strength with bodyweight, bands and dumbbells when there is no gym.', 3, 'You do not need a gym to get strong. Muscles respond to effort, not to where the weight came from. Gym move At home Barbell squat Goblet squat, Bulgarian split squat Bench press Push-up, dumbbell floor press Lat pulldown Band pulldown, door-frame row Romanian deadlift Single-leg dumbbell RDL Leg curl Sliding towel curl Same  strength gains with elastic bands as with weights Light loads  build muscle too when sets end close to failure Making light weights hard Slow down 3 seconds down on every rep. Go one-sided Single-leg and single-arm moves double the load. Pause Hold 2 s at the hardest point. More reps Take sets close to failure. Eight trials found bands and conventional weights gave similar strength gains. moderate', array['Lopes JSS et al. Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. SAGE Open Med 2019;7:2050312119831116.', 'Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res 2017;31(12):3508-3523.']::text[], '{"sources": {"lopes2019": "Lopes JSS et al. Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. SAGE Open Med 2019;7:2050312119831116.", "schoenfeld2017l": "Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res 2017;31(12):3508-3523."}, "blocks": [{"t": "lead", "text": "You do not need a gym to get strong. Muscles respond to effort, not to where the weight came from."}, {"t": "table", "head": ["Gym move", "At home"], "rows": [["Barbell squat", "Goblet squat, Bulgarian split squat"], ["Bench press", "Push-up, dumbbell floor press"], ["Lat pulldown", "Band pulldown, door-frame row"], ["Romanian deadlift", "Single-leg dumbbell RDL"], ["Leg curl", "Sliding towel curl"]], "source": null}, {"t": "stats", "items": [{"value": "Same", "unit": "", "label": "strength gains with elastic bands as with weights", "source": "lopes2019"}, {"value": "Light loads", "unit": "", "label": "build muscle too when sets end close to failure", "source": "schoenfeld2017l"}]}, {"t": "steps", "title": "Making light weights hard", "items": [{"title": "Slow down", "text": "3 seconds down on every rep."}, {"title": "Go one-sided", "text": "Single-leg and single-arm moves double the load."}, {"title": "Pause", "text": "Hold 2 s at the hardest point."}, {"title": "More reps", "text": "Take sets close to failure."}]}, {"t": "evidence", "text": "Eight trials found bands and conventional weights gave similar strength gains.", "source": "lopes2019", "grade": "moderate"}]}'::jsonb),
(35, 'women', 'E', 'Staying with it', 'Training as a woman', 'Lifting, the menstrual cycle and pregnancy: what the evidence says.', 4, 'Women respond to training the same way men do. Lifting builds strength and shape, not bulk, unless that is the goal. Myths Lifting makes women bulky You must train differently in each cycle phase Avoid exercise when pregnant Evidence Muscle builds slowly; heavy lifting builds strength and shape Cycle effects on performance are small and individual Exercise is safe and helpful in most pregnancies Trivial  average effect of cycle phase on performance 150 min a week of moderate activity during a healthy pregnancy Training with your cycle Track Note energy and mood in Habits. Adjust On low days lower the load a little; on good days push. Keep going No phase needs you to stop training. A meta-analysis of 78 studies found performance may be slightly lower in the early follicular phase, but effects were trivial and varied, so general phase-based rules are not supported. moderate Pregnant: usually fine Get your doctor''s go-ahead first Walking, cycling, swimming, light lifting Moderate effort: you can still talk Stop and seek care Bleeding or fluid leaking Dizziness, chest pain or headache Painful contractions', array['McNulty KL et al. The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Sports Med 2020;50(10):1813-1827.', 'Mottola MF et al. 2019 Canadian guideline for physical activity throughout pregnancy. Br J Sports Med 2018;52(21):1339-1346.']::text[], '{"sources": {"mcnulty2020": "McNulty KL et al. The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Sports Med 2020;50(10):1813-1827.", "mottola2018": "Mottola MF et al. 2019 Canadian guideline for physical activity throughout pregnancy. Br J Sports Med 2018;52(21):1339-1346."}, "blocks": [{"t": "lead", "text": "Women respond to training the same way men do. Lifting builds strength and shape, not bulk, unless that is the goal."}, {"t": "compare", "do": {"title": "Myths", "items": ["Lifting makes women bulky", "You must train differently in each cycle phase", "Avoid exercise when pregnant"]}, "dont": {"title": "Evidence", "items": ["Muscle builds slowly; heavy lifting builds strength and shape", "Cycle effects on performance are small and individual", "Exercise is safe and helpful in most pregnancies"]}}, {"t": "stats", "items": [{"value": "Trivial", "unit": "", "label": "average effect of cycle phase on performance", "source": "mcnulty2020"}, {"value": "150", "unit": "min a week", "label": "of moderate activity during a healthy pregnancy", "source": "mottola2018"}]}, {"t": "steps", "title": "Training with your cycle", "items": [{"title": "Track", "text": "Note energy and mood in Habits."}, {"title": "Adjust", "text": "On low days lower the load a little; on good days push."}, {"title": "Keep going", "text": "No phase needs you to stop training."}]}, {"t": "evidence", "text": "A meta-analysis of 78 studies found performance may be slightly lower in the early follicular phase, but effects were trivial and varied, so general phase-based rules are not supported.", "source": "mcnulty2020", "grade": "moderate"}, {"t": "compare", "do": {"title": "Pregnant: usually fine", "items": ["Get your doctor''s go-ahead first", "Walking, cycling, swimming, light lifting", "Moderate effort: you can still talk"]}, "dont": {"title": "Stop and seek care", "items": ["Bleeding or fluid leaking", "Dizziness, chest pain or headache", "Painful contractions"]}}]}'::jsonb),
(36, 'over-40', 'E', 'Staying with it', 'Training after 40', 'Why strength and balance matter more with age, and how to train safely.', 3, 'Muscle and balance fade with age unless you train them. It is never too late: older adults gain strength well. 3+ days a week of balance and strength work for adults 65 and over More training is needed by older adults to keep muscle size Example week after 40 Mon Strength Tue Walk Wed Balance Thu Strength Fri Walk Sat Strength Sun Rest Smart changes Longer warm-up 10 minutes, gradually heavier. Moderate reps 8 to 15 reps with good control. Balance every week Single-leg stands, step-ups, heel-to-toe walking. Recover 48 hours between hard sessions for the same muscles. WHO advises older adults to do varied balance and strength work on 3 or more days a week to prevent falls. strong', array['Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.', 'Bickel CS, Cross JM, Bamman MM. Exercise dosing to retain resistance training adaptations in young and older adults. Med Sci Sports Exerc 2011;43(7):1177-1187.']::text[], '{"sources": {"who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.", "bickel2011": "Bickel CS, Cross JM, Bamman MM. Exercise dosing to retain resistance training adaptations in young and older adults. Med Sci Sports Exerc 2011;43(7):1177-1187."}, "blocks": [{"t": "lead", "text": "Muscle and balance fade with age unless you train them. It is never too late: older adults gain strength well."}, {"t": "stats", "items": [{"value": "3+", "unit": "days a week", "label": "of balance and strength work for adults 65 and over", "source": "who2020"}, {"value": "More", "unit": "training", "label": "is needed by older adults to keep muscle size", "source": "bickel2011"}]}, {"t": "week", "title": "Example week after 40", "days": [{"day": "Mon", "label": "Strength", "kind": "strength"}, {"day": "Tue", "label": "Walk", "kind": "cardio"}, {"day": "Wed", "label": "Balance", "kind": "mobility"}, {"day": "Thu", "label": "Strength", "kind": "strength"}, {"day": "Fri", "label": "Walk", "kind": "cardio"}, {"day": "Sat", "label": "Strength", "kind": "strength"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "steps", "title": "Smart changes", "items": [{"title": "Longer warm-up", "text": "10 minutes, gradually heavier."}, {"title": "Moderate reps", "text": "8 to 15 reps with good control."}, {"title": "Balance every week", "text": "Single-leg stands, step-ups, heel-to-toe walking."}, {"title": "Recover", "text": "48 hours between hard sessions for the same muscles."}]}, {"t": "evidence", "text": "WHO advises older adults to do varied balance and strength work on 3 or more days a week to prevent falls.", "source": "who2020", "grade": "strong"}]}'::jsonb),
(37, 'mind-motivation', 'E', 'Staying with it', 'Mood, stress and motivation', 'Exercise as medicine for the mind, and how to keep going on low days.', 3, 'Training lifts mood, eases stress and improves sleep. Motivation comes and goes; routines carry you through. Exercise Eased depression in trials Walking or jogging Yes, among the best Yoga Yes, among the best Strength training Yes, among the best Mixed aerobic Yes Harder  sessions eased depression more than easy ones 66 days median time for a new habit to feel automatic On a low day Shrink it Do just the warm-up. Often you will keep going. Go outside A 10-minute walk counts. Tick it Log it in Habits; the streak matters more than the size. A network meta-analysis of 218 trials found walking, jogging, yoga and strength training eased depression, with effects comparable to therapy. Exercise adds to medical care; it does not replace it. moderate When exercise is not enough Feeling low most days for two weeks or more? Talk to a doctor; exercise works best alongside care. Keep moving and keep logging. Any thoughts of self-harm? Call Tele-MANAS on 14416 now, free and confidential. Reach out to someone you trust whenever it feels heavy.', array['Noetel M et al. Effect of exercise for depression: systematic review and network meta-analysis of randomised controlled trials. BMJ 2024;384:e075847.', 'Lally P, van Jaarsveld CHM, Potts HWW, Wardle J. How are habits formed: modelling habit formation in the real world. Eur J Soc Psychol 2010;40(6):998-1009.']::text[], '{"sources": {"noetel2024": "Noetel M et al. Effect of exercise for depression: systematic review and network meta-analysis of randomised controlled trials. BMJ 2024;384:e075847.", "lally2010": "Lally P, van Jaarsveld CHM, Potts HWW, Wardle J. How are habits formed: modelling habit formation in the real world. Eur J Soc Psychol 2010;40(6):998-1009."}, "blocks": [{"t": "lead", "text": "Training lifts mood, eases stress and improves sleep. Motivation comes and goes; routines carry you through."}, {"t": "table", "head": ["Exercise", "Eased depression in trials"], "rows": [["Walking or jogging", "Yes, among the best"], ["Yoga", "Yes, among the best"], ["Strength training", "Yes, among the best"], ["Mixed aerobic", "Yes"]], "source": "noetel2024"}, {"t": "stats", "items": [{"value": "Harder", "unit": "", "label": "sessions eased depression more than easy ones", "source": "noetel2024"}, {"value": "66", "unit": "days", "label": "median time for a new habit to feel automatic", "source": "lally2010"}]}, {"t": "steps", "title": "On a low day", "items": [{"title": "Shrink it", "text": "Do just the warm-up. Often you will keep going."}, {"title": "Go outside", "text": "A 10-minute walk counts."}, {"title": "Tick it", "text": "Log it in Habits; the streak matters more than the size."}]}, {"t": "evidence", "text": "A network meta-analysis of 218 trials found walking, jogging, yoga and strength training eased depression, with effects comparable to therapy. Exercise adds to medical care; it does not replace it.", "source": "noetel2024", "grade": "moderate"}, {"t": "flow", "title": "When exercise is not enough", "items": [{"q": "Feeling low most days for two weeks or more?", "yes": "Talk to a doctor; exercise works best alongside care.", "no": "Keep moving and keep logging."}, {"q": "Any thoughts of self-harm?", "yes": "Call Tele-MANAS on 14416 now, free and confidential.", "no": "Reach out to someone you trust whenever it feels heavy."}], "note": null, "source": null}]}'::jsonb),
(38, 'how-levlofit-works', 'E', 'Staying with it', 'How Levlofit builds your plan', 'Levels, level checks, the foundation phase and why goals unlock one at a time.', 3, 'Levlofit is built level first. You train your main goal until the basics are solid, then new goals unlock. The Levlofit ladder 0 Starting out Learn the moves, build the habit. 1 Foundation Basic strength and fitness in place. 2 Building Steady progress on your main goal. 3 Solid A good level for most people. 4 Advanced Specialised training pays off. 5 Expert Coach-led territory. How you move up Train the plan Log your sets Take the level check Unlock the next level What decides your plan Your answers Health check, body numbers, days, time and equipment. Your level From the level check in Workout. Rules, not AI Numbers come from cited rules; Levlofit AI explains them, never invents them. Going from no resistance training to regular training gives the biggest gains, so Levlofit builds the basics before adding goals. strong Change anytime in Protocol Goals and main goal Training days and time Diet, allergies and budget Earned, not edited Your level When new goals unlock', array['Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.']::text[], '{"sources": {"acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026."}, "blocks": [{"t": "lead", "text": "Levlofit is built level first. You train your main goal until the basics are solid, then new goals unlock."}, {"t": "scale", "title": "The Levlofit ladder", "items": [{"mark": "0", "label": "Starting out", "text": "Learn the moves, build the habit."}, {"mark": "1", "label": "Foundation", "text": "Basic strength and fitness in place."}, {"mark": "2", "label": "Building", "text": "Steady progress on your main goal."}, {"mark": "3", "label": "Solid", "text": "A good level for most people."}, {"mark": "4", "label": "Advanced", "text": "Specialised training pays off."}, {"mark": "5", "label": "Expert", "text": "Coach-led territory."}], "source": null}, {"t": "cycle", "title": "How you move up", "items": ["Train the plan", "Log your sets", "Take the level check", "Unlock the next level"]}, {"t": "steps", "title": "What decides your plan", "items": [{"title": "Your answers", "text": "Health check, body numbers, days, time and equipment."}, {"title": "Your level", "text": "From the level check in Workout."}, {"title": "Rules, not AI", "text": "Numbers come from cited rules; Levlofit AI explains them, never invents them."}]}, {"t": "evidence", "text": "Going from no resistance training to regular training gives the biggest gains, so Levlofit builds the basics before adding goals.", "source": "acsm2026", "grade": "strong"}, {"t": "compare", "do": {"title": "Change anytime in Protocol", "items": ["Goals and main goal", "Training days and time", "Diet, allergies and budget"]}, "dont": {"title": "Earned, not edited", "items": ["Your level", "When new goals unlock"]}}]}'::jsonb);
